-- Generated source references; not native quest records.
local addon = WordHunterWoW_Addon
local compat = addon and addon.Compat
local flavor = compat and compat.GameFlavor and compat.GameFlavor()
if not (flavor == "retail") then return end
local pack = WordHunterWoW_QuestSources and WordHunterWoW_QuestSources["multilanguage-retail"]
if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[29538] = { id = 29538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Them Bleed", description = "The Maker uses demon blood and a special rod to turn brown and green orcs into red ones. We'd like to see if we can take that blood, mess around with it a bit, and make it turn orcs of all colors into harmless docile lumps. \n\nYou're going to bring me some samples of their blood so we can see. Don't forget to grab that rod!", progress = "You have that blood, darlin'?  Might be kind of important if we asked you to get it, you know?", completion = "Out-frikkin-standing! As of right now, you are my eighth favorite person on the smoldering remains of this sorry planet!", objectives = "Collect 10 Fel Orc Blood Vials and a Fel Infusion Rod for Gunny.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29539] = { id = 29539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of Rage", description = "As it turns out, the eggheads back at Honor Hold can't see much into this place. Bunch of lying lazy mages, is what they are.\n\nEither way, we don't really know exactly what's going on in here. So, you're going in to find out!", completion = "<You tell Gunny everything you saw in the Blood Furnace.>\n\nYou brought back some loot for ol' Gunny, right?\n\nNo, no, you're right, clearly I owe you a reward for all your hard work. Not like Gunny didn't arrange all this and send you in there in the first place.", objectives = "Fully investigate the Blood Furnace and then report back to Gunny.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29540] = { id = 29540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Breaker", description = "So they've got this big ol' demon stashed away in this place, is what they're telling me. And there's an orc that's in charge of keeping him under wraps.\n\nKilling an orc is killing an orc, am I right? Doesn't matter what he did or what he's doin', orcs are always ripe for the slaughter!", completion = "Really? You want a reward for killing an orc? As in fame and riches and noble steeds?\n\nBack in my day killing orcs WAS the reward!", objectives = "Kill Keli'dan the Breaker and return to Gunny.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29541] = { id = 29541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Care of It", description = "This looks bad... you'd better do something.", objectives = "Resolve the dispute any way you see fit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29542] = { id = 29542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invading the Citadel", description = "With the Legion to one side and the fel orcs to the other, Thrallmar is going to be overrun if we don't do something about it.\n\nHead west to the Hellfire Ramparts and speak with Stone Guard Stok'ton. He's in charge of a covert operation to start a Horde invasion on the entire citadel.", completion = "Shatterskull's not personable by anyone's standards, but he certainly gets the job done. Let's put you to work.", objectives = "Speak with Stone Guard Stok'ton in Hellfire Ramparts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29543] = { id = 29543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invading the Citadel", description = "With the Legion to one side and the fel orcs to the other, Honor Hold is going to be overrun in a matter of time if we don't do something about it.\n\nHead west to the Hellfire Ramparts and speak with Advance Scout Chadwick. He's in charge of a covert operation to start an Alliance invasion on the entire citadel.", completion = "That Altumus is certainly a gem, isn't she? But there won't be any of us left alive out here if we aren't successful in our efforts in the ramparts.", objectives = "Speak with Advance Scout Chadwick in Hellfire Ramparts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29544] = { id = 29544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blood Furnace", description = "Caza'rez awaits you within the Blood Furnace. He's already cleared out a small area and has our scryers hard at work figuring out what's going on down there.\n\nBut I don't trust that scrying will be enough. I'm sure Caza'rez has plans in mind for a solid blade or two. I want you to go there and lend him your expertise in dealing with the fel orcs.", sourceObjective = "Speak with Caza'rez in the Blood Furnace.", sourceObjectiveStatus = "unverified-source-field" }
quests[29545] = { id = 29545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blood Furnace", description = "This war is far from over. We need to stop the flow of new recruits to the fel orc front if we are to have any hope of victory.\n\nTravel to the Blood Furnace and speak with Gunny, he's secured a small area within and I'm sure he could use your assistance. Be forewarned, Gunny is...unusual.", sourceObjective = "Speak with Gunny in the Blood Furnace.", sourceObjectiveStatus = "unverified-source-field" }
quests[29546] = { id = 29546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tipping the Scales", description = "These blasted native monkey savages have been assaulting us since the day we put to shore!\n\nWe were holding our own until they kidnapped half our men, including the Admiral.\n\nJust look at their numbers! They're endless, and we're standing on our last legs.\n\nIf you're here to get us out of this mess, go help take down some monkeys.\n\nIt's them or us, {race}!", objectives = "Kill 12 Hozen Ravagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29547] = { id = 29547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The King's Command", description = "Greetings, {class}.\n\nI have been asked to assemble a team for a high priority mission.\n\nPlease come to Stormwind Keep immediately for a briefing with King Varian Wrynn. I will be waiting in the King's war room.", completion = "Our role is of utmost importance. Admiral Taylor and his flagship have gone missing. More importantly, the young Prince was with him, and it is our primary objective to bring him back home safely.", objectives = "Find Grand Admiral Jes-Tereth in the war room at Stormwind Keep in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29548] = { id = 29548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mission", description = "Well, you heard the King. Admiral Taylor's last transmission came from somewhere in the southern seas.\n\nWe will begin our search from the air! Locating the Prince - the White Pawn - is of critical priority.\n\nThe Skyfire is fueled, supplied, and ready to depart. She and her crew idle in the sky just north of the harbor.\n\nMake your last preparations, then meet Admiral Rogers on the deck. We will depart without delay.", progress = "Ah, a veteran of the Cataclysm campaigns! Good, I could use more experienced hands.", completion = "That's a whole Horde base down there! Where was our intel?\n\nWell {class}, it's time to see what this upgraded gunship is capable of.", objectives = "Report to Admiral Rogers on The Skyfire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29549] = { id = 29549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flightmaster Down", description = "I've taken stock of the missing, and among them is Donovar Murall, our Flightmaster.\n\nHe is not only a vital part of our crew, he is a dear friend as well.\n\nPlease find him and bring him back alive.", sourceObjective = "Speak to Donovar Murall in Veridian Grove.", sourceObjectiveStatus = "unverified-source-field" }
quests[29550] = { id = 29550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Snowpuff", description = "<Donovar bursts into tears upon seeing you.>\n\nTh-th-those blasted monkey hooligans d-d-dragged me inta these woods. I thot I were dunnert, but mah faithful Snowpuff came flyin' to mah rescue!\n\nShe fought 'em off and then they all jumped 'er! Wot with them apes prowlin' around, she's...\n\n<Donovar blows his nose loudly.>\n\n...she's done for! Wahaahaaaaaa! Unless...\n\nListen {class}, I saw Gingerleaf growing all over these woods. I beg ya, bring me some o' that healing herb and Snowpuff just might make et!", objectives = "Collect 4 Gingerleaf for Snowpuff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29551] = { id = 29551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grove Stalkers", description = "We're still trying to take stock of our crew after the fighting.\n\nI'm afraid many of them are stranded out in the woods, probably wounded and fighting to survive.\n\nWe know that the forest to the north is full of vicious tigers.\n\nGo clear them out of the woods. You'll give more of our men and women a chance to make it back alive.", objectives = "Kill 8 Grove Stalkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29552] = { id = 29552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Critical Condition", description = "We may have won the first battle, but a critical task still remains.\n\nDozens of Skyfire pilots were shot down during the initial aerial battle.\n\nWithout medical aid, their condition will deteriorate over time, until they finally perish. We are their only hope for survival.\n\nGo into the orchard and revive as many pilots as you can find.\n\nWe will leave no one behind.", progress = "We will remember all the brave Alliance soldiers who fell today. Though they can no longer continue, we carry the fight onward.", completion = "Good work, {name}. Those soldiers will live and fight another day because of your efforts.", objectives = "Revive 6 Wounded Pilots in Paw'don Glade. You can also use healing spells or bandages to revive them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29553] = { id = 29553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Admiral", description = "Alright. According to the clues you found, that was Anduin's ship, and Admiral Taylor was the captain. \n\nAnd Admiral Taylor's last entry says he was going to fight off the hozen and protect the vessel after the shipwreck.\n\nThe locals say these hozen sometimes take prisoners, and I didn't see Taylor's corpse anywhere among the wreckage. So you'll probably find Taylor at the hozen encampment to the northeast.\n\nGet going, we have no time to lose!", completion = "<You found him, but the Admiral is unconscious. He looks on the verge of death.>", objectives = "Find Admiral Taylor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29554] = { id = 29554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunken Junk", description = "Hey {name}!\n\nThe coast here is littered with scraps of tools and metal from the shipwreck.\n\nThe ordinary person might think that this is junk, but I'm sure I can salvage most of it. I once repaired a submarine using only a bronze tube and a luffa!\n\nGet me some of the waterlogged scraps along the shore by the ship. I need them for my next project.", objectives = "Collect 8 Waterlogged Scraps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29555] = { id = 29555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The White Pawn", description = "Alright, soldier. I've got a critical mission for you.\n\nGet down to the coastline south of here - in the cove there you'll find a wrecked Alliance vessel. I need you to search it and find out if it was the ship that was carrying Anduin. \n\nThen, recover the Captain's Log and see if it has any information on where we can find him.\n\nSince the log is from a military ship, it'll be written using a cipher - take it to Nodd Codejack afterwards. He's keeping watch on the wreck from the other end of the cove.", progress = "Well?", completion = "Alright... let me see... using the cipher from when the ship went missing...\n\n<Nodd is clearly doing some calculations in his head.>\n\nAha!", objectives = "Search the Wreck of the Vanguard in Jade Forest for clues about its cargo, and recover the Encoded Captain's Log.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29556] = { id = 29556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hozen Aren't Your Friends, Hozen Are Your Enemies", description = "We've located an Alliance wreck to the south. Unfortunately, the locals have informed us that it's currently being scavenged by a group of creatures called \"hozen.\"\n\nBy pillaging our wrecked ships, these creatures have already shown that they aren't friendly. We can't have them taking spoils from our ships, stealing our supplies, and worse, potentially capturing or killing any survivors.\n\nGet down there and take them out! When you're done, meet up with Nodd Codejack, our SI:7 agent in the area.", completion = "Good work. Dirty creatures trying to kick us when we're down... \n\nThat'll teach 'em to try and salvage an Alliance vessel!", objectives = "Kill 10 Hozen at the Wreck of the Vanguard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29557] = { id = 29557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mission Continues", description = "The King's flagship went aground not far from here.\n\nApparently, the ship signaled Anduin's safe arrival shortly after landing, but when they sent men to retrieve the Prince, he was gone.\n\nI want to investigate the wreckage for clues.\n\nNodd and Sully are already at the crash site. Go east along the beach and see if they need help.", sourceObjective = "Speak to Nodd at Sapphire's End in the Jade Forest.", sourceObjectiveStatus = "unverified-source-field" }
quests[29558] = { id = 29558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of War", description = "I see you want to save your friend. I can help you, if you will help me.\n\nFirst of all, it should be obvious that the fewer the Slingtail roaming around, the easier it will be to escape.\n\nKill the hozen guards around us, and we will be one step closer to freedom.", progress = "You fight well, foreigner.", completion = "Ahahaha! You are brave.\n\nAn admirable trait.", objectives = "Kill 12 Slingtail Treeleapers or Slingtail Mudseers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29559] = { id = 29559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freeing Our Brothers", description = "You may be an outsider, but you and I have a common enemy in the hozen.\n\nMany members of my tribe are trapped in cages nearby. I have also seen your... Alliance... soldiers as well.\n\nI cannot leave without freeing my brethren, just as you cannot leave yours.\n\nThe Slingtail hold the keys to those cages. Find the keys and free our friends.", progress = "Are they freed?", completion = "You have freed my brothers? Good.\n\nWe are in your debt.", objectives = "Free 6 Jinyu Prisoners or Alliance Prisoners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29560] = { id = 29560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Power", description = "Hozen skulls are prized tokens among my village.\n\nWe use them to perform ceremonial rites, and the older the skull, the more potent its magic.\n\nLuckily for us, the hozen are careless, filthy beasts. They leave the skulls of their dead scattered among their huts and campfires.\n\nCollect these skulls for me, and I will reward you handsomely.", progress = "The skulls are precious to my tribe. How many have you collected?", completion = "It is good to see that you are so resourceful, {name}. It is a trait admired by my people.\n\nThe fine specimens you have brought me will produce powerful magic.", objectives = "Collect 8 Ancient Hozen Skulls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29561] = { id = 29561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against the Odds", description = "You and I are the only mission operatives who made it to base camp, {class}.\n\nI saw the other SI:7 eject over the forest to the north.\n\nYou'd better go quickly and rescue any survivors.", objectives = "Find the lost SI:7 agents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29562] = { id = 29562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jailbreak", description = "Without healing, your friend Taylor will die. My village is just east of here, in the middle of the large lake.\n\nI will take Taylor myself, but the fighting is most dangerous in that direction.\n\nI need you to help clear a path through the hozen, so that I may run safely into my village.\n\nCan you do this?", progress = "Our conflict with the hozen goes back many generations.", completion = "Thank you, {name}. Because of you, we were able to make it here safely.", objectives = "Kill 10 Slingtail Fishrippers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29563] = { id = 29563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in Action", description = "You have to help me! We were sent here to investigate the various parts of the reservoir, but my friends haven't come back yet, and it's been a long time.\n\nThat's why I need you to discover what became of them. Naturalist Bite and Weeder Greenthumb went this way.", progress = "Have you discovered anything?", completion = "The loss of life...it pains me.\n\n<Watcher Jhang sighs.>\n\nThank you, {name}. When we are all reunited, the naga won't stand a chance.", objectives = "Discover what happened to Naturalist Bite and Weeder Greenthumb. Then, return to Watcher Jhang.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29564] = { id = 29564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Brother Betrayed", description = "My village was able to escape the naga onslaught at first. We would have all made it to Nagrand had it not been for my brother. He sold our souls for his own freedom.\n\nNow he works here as a slave driver, whipping his own brothers until their backs bleed. Make Mennu pay, {race}.", progress = "Is the traitor dead?", completion = "Mennu's death will not fix the broken backs of my family and friends, but it will give them a chance to live the rest of their lives free.", objectives = "Kill Mennu the Betrayer, then return to Nahuud.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29565] = { id = 29565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Matter", description = "From what Nahuud has told me, two mighty creatures, Rokmar the Crackler and Quagmirran, were among the first enslaved by the naga when they arrived. They helped to subjugate many of the native races of Zangarmarsh.\n\nThough it pains me greatly to ask you to do so, you must put them down.", progress = "Did you slay them?", completion = "I'm glad that their spirits are now free. I wish we could say the same for the rest of their kind.\n\nThere is still much work to be done, especially elsewhere in Coilfang.", objectives = "Bring The Invader's Claw and The Slave Master's Eye to Watcher Jhang.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29566] = { id = 29566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Checking Up", description = "These marshes are beautiful, wouldn't you agree? That is, except for the naga forces draining the water away.\n\nI sent a small expedition to the Coilfang Reservoir to investigate the naga, and they haven't returned. I'm concerned that something has happened to them.\n\nWould you travel to the Slave Pens underneath Serpent Lake and find Watcher Jhang?", completion = "What're you doing all the way down here? As you can see, it isn't exactly safe!", objectives = "Speak with Watcher Jhang in the Slave Pens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29567] = { id = 29567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalk the Stalker", description = "The spore giants may be attacking my people today, but the marsh walkers have taken more innocent lives than any creature I've ever seen. They are our ancient enemies.\n\nTheir brood mother, the Black Stalker, resides deep within this bog. If you were to destroy her and bring me her brain as proof, I would tell tales of your bravery to my grandchildren.", progress = "You have returned.  Does this mean that The Black Stalker is no more?", completion = "The Black Stalker is dead!  Normally I would not revel in such butchery, but the pain that the great mother and her brood have put my people through over the centuries is unspeakable.\n\nYou have my deepest thanks, brave {class}.", objectives = "Bring the Brain of the Black Stalker to T'shu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29568] = { id = 29568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Necessary Evil", description = "Hungarfen and Quagmirran used to jointly rule over the spore giants. With Quagmirran gone, the burden rests solely on Hungarfen's tendrils.\n\nWe have no choice but to put the giant down before he can be enslaved and turned into a weapon.", progress = "Is the deed done, {name}?", completion = "You've done all of Zangarmarsh a favor this day, {name}. The spore giants may be naturally aggressive, but they're still a vital part of the ecosystem.", objectives = "Kill Hungarfen, then report back to Naturalist Bite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29569] = { id = 29569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlord Kalithresh's Prized Possession", description = "Warlord Kalithresh has been utilizing the Underbog as a sort of breeding ground for Ghaz'an, a powerful hydra that he plans to unleash upon Zangarmarsh once it is fully grown.\n\nI fear nobody will be able to stop the naga if the beast reaches its full size. Find Ghaz'an and slay him for the good of us all.", objectives = "Kill Ghaz'an and bring his scale to Watcher Jhang.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29570] = { id = 29570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescuing the Expedition", description = "The last members of my expedition are somewhere in here. We're going to need the knowledge they've gathered and their skills if we're to have any chance at defeating the naga.\n\nSee if you can find Earthbinder Rayge and Windcaller Claw, and make sure they're ok.", progress = "Were you able to find either of them? Are they ok?", completion = "Soon we'll all be together again, and I owe it all to you!\n\nWe'll bring the naga down before you know it, they don't stand a chance!", objectives = "Discover what happened to Earthbinder Rayge and Windcaller Claw. Then, return to Watcher Jhang.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29571] = { id = 29571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defending the Wilds", description = "The Earthen Ring often finds itself working closely with the druids of the Cenarion Circle. Now is one such time.\n\nTravel north to the Underbog and speak with Watcher Jhang. She is in charge of an expedition in the Coilfang Reservoir to stop the naga there and save Zangarmarsh.", completion = "The Underbog lies precariously on the edge of becoming another part of the Coilfang naga system. You must help us!", objectives = "Speak with Watcher Jhang in the Underbog.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29572] = { id = 29572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety Is Job One", description = "Shaffar's ethereals have completely blocked us out of the Mana-Tombs. Thankfully, I've got a plan. While we can't go in through the front door, there are sure to be several transporters inside.\n\nI want you to clear the way for my crew first and then I want you to activate one of their transporters to teleport us inside.\n\nActivate the teleporter in the chamber right before Shaffar's chambers when the way has been cleared. Don't worry, I'll make it worth your while...", objectives = "Artificer Morphalius wants you to kill 10 Ethereal Crypt Raiders, 5 Ethereal Sorcerers, 5 Nexus Stalkers and 5 Ethereal Spellbinders.\n\nOnce that's done, find the Ethereal Transporter in the chamber before Shaffar's and activate it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29573] = { id = 29573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety is Job One", description = "It's nearly safe for our men to come in here and take what's rightfully ours. The real danger now is Shaffar's personal army that he has crawling all over this place.\n\nI need you to take care of his forces for me while I regain my strength.", progress = "Done already? You humans continue to fascinate me.", completion = "Splendid! Haramad will be delighted to hear the good news! All of this ripe for his taking!", objectives = "Kill 10 Ethereal Crypt Raiders, 5 Ethereal Sorcerers, 5 Nexus Stalkers, and 5 Ethereal Spellbinders, then return to Artificer Morphalius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29574] = { id = 29574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intriguing Specimens", description = "There is a creature not far inside these halls called Pandemonius who is able to twist void energies to sustain and empower itself.\n\nA bit further in lies Tavarok, a being that takes those same void energies and converts them into a crystalline structure stronger than any I've ever seen!\n\nI absolutely must obtain samples for further study.", progress = "If you don't have what I'm looking for, stop wasting my time.", completion = "These samples are absolutely fascinating. They'll work very nicely.", objectives = "Bring Pandemonius' Essence and Tavarok's Heart to Mamdy the \"Ologist\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29575] = { id = 29575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undercutting the Competition", description = "With his ward in place and his forces ready, Nexus-Prince Shaffar has been able to pillage this place for all it's worth without so much as an ounce of trouble.\n\nUnsurprisingly, Nexus-Prince Haramad isn't pleased by this, and has placed a hefty bounty on Shaffar's head.", progress = "Were you interested in the bounty on Shaffar's head?", completion = "I didn't honestly think a {race} would be able to defeat a Nexus-Prince. You've surprised me, and you've earned the handsome reward you were promised.", objectives = "Bring Shaffar's Wrappings to Artificer Morphalius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29576] = { id = 29576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Air of Worry", description = "My sight has long since faded, but when the wind is right I can still smell the blossoms of Nectarbreeze Orchard as if they were in my own palm.\n\nToday, though, their fragrance is muddled with smoke. Please, if you are able, check in on the orchard and see that things are okay. Perhaps my old nose is playing tricks on me.\n\nYou'll find the orchard to the southwest, beyond the statue of the Jade Serpent.", completion = "If you've come to speak with my fists, take your place in line. Otherwise, I could use your help.", objectives = "Speak with Shao the Defiant at Nectarbreeze Orchard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29577] = { id = 29577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashyo's Vision", description = "Have a look at that!\n\n<Ashyo motions at the massive waterfall to the north.>\n\nThis must be the water supply for the whole valley!\n\nThink about it, {name}: the pandaren use this water to grow vegetables the size of a house. Where could it come from? What is so special about it?\n\nThe elders among my people know a technique for speaking with the water and divining the future. Perhaps this same technique can provide insight into the water's source...\n\nIt's worth a shot at least!", progress = "What is that jinyu up to over there?", completion = "I can't believe he was able to see that with a stick... perhaps there is more to \"crazy jinyu rituals\" than we thought.", objectives = "Speak with Ashyo at the Pools of Purity and observe his ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29578] = { id = 29578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defiance", description = "The damn mogu hit us out of nowhere! Anyone they don't kill on sight is being dragged away into the woods.\n\nThis is the only safehouse, and its all I can do to hold the door.\n\nWhat do you say, friend? Are you willing to stand up and fight for the weak?", progress = "Don't worry - they won't get through me.", completion = "Nice work, but there's more to be done if we are to save this village.", objectives = "Kill 8 Gormali Raiders and 8 Gormali Incinerators in Nectarbreeze Orchard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29579] = { id = 29579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rally the Survivors", description = "The people of this village are simple farmers - not fighters like you and I. Still, they are stubbornly defending their homes as best they can.\n\nSearch the village for anyone still on their feet and tell them to rally here at Hanae's place.", progress = "Please tell me some still live...", completion = "They're inside. Shaken, but alive thanks to you.", objectives = "Speak with 5 Nectarbreeze Farmers around Nectarbreeze Orchard and send them to the safehouse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29580] = { id = 29580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orchard-Supplied Hardware", description = "They may not be weaponmasters, but many of these farmers can wield a simple hoe or a rake as an extension of their own will.\n\nThat mastery coupled with the right motivation could muster a force capable of standing against the mogu.\n\nIf you can bring back some tools from the orchard, I'll distribute them to anyone willing to fight.", progress = "Were there any tools left?", completion = "There are no hunters among us, but we'll fight to protect our loved ones.", objectives = "Retrieve 6 Orchard Tools from Nectarbreeze Orchard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29581] = { id = 29581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Golden Dream", description = "Ashyo must have experienced what we call the golden dream.\n\nMany of us working here have seen it, too - often after a long day of toiling in the pools. It is said this vision--and the feeling of elation it brings--is a reward to the mind for working the body.\n\nThere IS an easier way, though we rarely resort to it anymore: a tea can be brewed using lotus root and dreamleaf, which grows around the shrine on the upper tier.\n\nBring the dreamleaf to Yan back in town and he can brew the tea for you.", progress = "Yes, did you need something?", completion = "Ah... dreamleaf! So you want to see the Golden Dream, do you?\n\nCome to think of it, I haven't seen the Dream in years - not since I was a cub spending long hours playing in the pools. Long before I took up the culinary arts.\n\nLooks like you brought enough dreamleaf for two cups of tea... so why not?\n\nHere's to better days!", objectives = "Bring a Sprig of Dreamleaf to Yan in New Cifera.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29582] = { id = 29582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grek's Crazy Night", description = "Grek had bad night last night.\n\nShiny mummy man came into Grek's house and told Grek that he had to go to Mana Tombs in Auchindoun. But Grek still trying to read wanted poster!\n\n<Grek's face lights up.>\n\nGrek knows! You go find shiny mummy man and tell him Grek sent you. It perfect plan!", completion = "That meathead send you instead?\n\n<Artificer Morphalius looks you over.>\n\nI suppose you'll have to do.", objectives = "Speak with Artificer Morphalius in the Mana Tombs in Auchindoun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29583] = { id = 29583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eckert the Mad", description = "I'm a skilled engineer, a brilliant inventor, the heart of any party, and the best dancer Azeroth has ever seen.\n\nDo they call me those things? No.\n\nBut you have one run-in with an ethereal and all of the sudden everyone and their mother calls you \"the mad\".\n\nI saw one right here just yesterday, I swear it! He said if I followed him to the Mana Tombs in Auchindoun there would be vast treasure and ancient knowledge awaiting me!", completion = "I was truly hoping that the gnome I sought out would be the one to answer my call.\n\n<Artificer Morphalius looks you over.>\n\nI suppose you'll do.", objectives = "Speak with Artificer Morphalius in the Mana Tombs in Auchindoun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29584] = { id = 29584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Mogu Firestarters", description = "As if the attack weren't bad enough, the mogu are setting these ancient orchards ablaze.\n\nI cannot understand what they hope to achieve, but we must stop them. Clear out the orchard so these people have a livelihood to return to.", objectives = "Kill 8 Mogu Firestarters in Nectarbreeze Orchard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29585] = { id = 29585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitfire", description = "We've tended these orchards and made cider from their nectar for generations. In that time, we've learned a special trick for putting out fires in a pinch.\n\n<Hanae pushes a jug of cider into your hand.>\n\nThe cider itself - when mixed with crushed gingerleaf and saliva - quickly becomes sticky and viscous. Perfect for smothering flames.\n\nPlease, while you're out there, try to get the flames under control. I've already mixed in the gingerleaf, just swig and spit.", progress = "Best not to judge our prized cider by its flavor in this state.", completion = "A survivor came in moments ago and said the flames are beginning to die down.\n\nWe owe our very way of life to you, stranger. I cannot possibly reward you adequately, but please take this.", objectives = "Use the Nectarbreeze Cider to put out 12 fires around Nectarbreeze Orchard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29586] = { id = 29586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Splintered Path", description = "First... before the war-cries... we heard the trees.\n\nGroaning, creaking, and finally crashing down as the mogu cut their way through the woods. They were making the return trip easier...\n\nThey're dragging our friends back down that path, to the ruins west of the village! Those ruins have been empty for years - our children play there.\n\nWhy would the mogu come back to them now?", completion = "This doesn't look like a quick snatch and run. They're setting up for something big.", objectives = "Follow the path of fallen trees from the northwest corner of Nectarbreeze Orchard and find the mogu raiders camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29587] = { id = 29587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbound", progress = "Those ropes should give with a strong tug.", completion = "The pandaren were subjected to mogu rule in ancient times - we'll never let it happen again.", objectives = "Set 10 Captured Nectarbreeze Farmers free in Camp Gormal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29590] = { id = 29590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dead Watcher", description = "A terrifying otherworldly being haunts both the spirit and physical worlds. We call it Shirrak.\n\nIt can only be harmed in your realm. Please help rid us of this nightmare.", completion = "Perhaps now we can finally be at peace.", objectives = "Kill Shirrak the Dead Watcher, then return to the Draenei Spirit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29591] = { id = 29591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raging Spirits", description = "The Auchenai have turned their backs on everything we used to stand for. They've taken to raising the dead as unholy minions!\n\nThis cannot stand. Put the spirits back to rest, and massacre those responsible for raising them into undeath.", progress = "Don't speak to me again until the deed is done.", completion = "The dead belong in the spirit realm. Just as you belong in this one.", objectives = "Slay 5 Angered Skeletons, 5 Raging Skeletons, and 3 Auchenai Necromancers, then return to the Tormented Soulpriest in Auchenai Crypts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29592] = { id = 29592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caster Legendary BREADCRUMB TRACKER" }
quests[29593] = { id = 29593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitting Them Where It Hurts", description = "The fel orcs have stockpiled many of their supplies here.\n\nStealing them would be a severe blow to their war effort and a great boon to ours. Are you up to the task, {class}?", progress = "How many piles were you able to take?", completion = "Well done! The long term effects of this attack will be far worse than slaying a few orcs could ever be.", objectives = "Steal 3 piles of Hellfire Supplies, then return to Stone Guard Stok'ton in Hellfire Ramparts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29594] = { id = 29594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitting Them Where It Hurts", description = "The fel orcs have stockpiled many of their supplies here.\n\nStealing them would be a severe blow to their war effort and a great boon to ours. Are you up to the task, {class}?", progress = "How many piles were you able to take?", completion = "Well done! The long term effects of this attack will be far worse than slaying a few orcs could ever be.", objectives = "Steal 3 piles of Hellfire Supplies, then return to Advance Scout Chadwick in Hellfire Ramparts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29595] = { id = 29595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everything Will Be Alright", description = "You've had quite an adventure, {name}. And before you've even set foot inside of the Auchenai Crypts.\n\nI am one of the fortunate spirits. I was neither bound to Levixus nor a part of Exarch Maladaar's vile experiments in necromancy. While you have destroyed Levixus, Maladaar lives on, continuing to torment the spirits inside the crypts.\n\nWhat I ask is simple. Enter the Auchenai Crypts and speak with the Draenei Spirit there. You must destroy Exarch Maladaar.", completion = "Welcome to the Auchenai Crypts, {name}, where our two worlds meet.", objectives = "Greatfather Aldrimus standing outside the Auchenai Crypts of Auchindoun has asked that you enter the Auchenai Crypts and speak with the Draenei Spirit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29596] = { id = 29596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End of the Exarch", description = "Exarch Maladaar performs his unholy work in the deepest part of the crypts. He poses a threat to both of our worlds if he is not stopped.\n\nYou must slay him for the benefit of us all, dead and alive.", completion = "You have done our realm a great service. You will not be forgotten.", objectives = "Kill Exarch Maladaar and return to the Draenei Spirit inside the Auchenai Crypts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29597] = { id = 29597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End of the Exarch", description = "Exarch Maladaar performs his unholy work in the deepest part of the crypts. He poses a threat to both of our worlds if he is not stopped.\n\nYou must slay him for the benefit of us all, dead and alive.", objectives = "Kill Exarch Maladaar and return to the Draenei Spirit inside the Auchenai Crypts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29598] = { id = 29598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taretha's Diversion", description = "It was Taretha who created the original diversion at Durnholde, allowing Thrall to escape.\n\nNow the Infinite have captured Taretha. The diversion will not happen without our involvement. You must use the incendiary devices that I give you and burn down the internment lodges.", progress = "Who are you?", completion = "You are friends of Taretha? So this is her new plan? Very well then...", objectives = "Travel to Durnholde Keep and set 5 incendiary charges at the barrels located inside each of the internment lodges using the Pack of Incendiary Bombs given to you by Erozion.\n\nSpeak to Thrall in the basement prison of Durnholde Keep when you have the Internment Lodges Set Ablaze.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29599] = { id = 29599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from Durnholde", description = "I have plans for my people, stranger.\n\nOne day, they shall overthrow their oppressors and rise as one. They will break free from the bonds that hold them and from that uprising shall be born the orcish Horde.\n\nWe will leave when you are ready.", progress = "<Erozion nods.>", completion = "You have done a great thing, {name}. Alas, the young warchief's memory of these events must be as they originally were...", objectives = "When you are ready to proceed, let Thrall know. Follow Thrall out of Durnholde Keep and help him free Taretha and fulfill his destiny.\n\nSpeak with Erozion in Old Hillsbrad should you complete this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29600] = { id = 29600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snap Judgment", description = "These pools are very special: they nurture life like nothing else in Pandaria.\n\nUnfortunately this means they draw all kinds of attention from local fauna. Recently, dragon turtles have discovered that toadspawn pools are common on the tier just above us. They're running wild up there, trampling the lotuses and snapping at my workers.\n\nThey aren't much of a threat on their own, but in groups they can be pretty nasty. Please, if you can spare your strength, help clear them out.", progress = "<Yue sighs.>\n\nIf only we'd kept up with our maintenance, the situation would not have come to this.", completion = "You have my gratitude, {name}.\n\nPlease take this as a token of my appreciation.", objectives = "Kill 16 Razorback Snappers at the Pools of Purity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29601] = { id = 29601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkmoon Field Guide", description = "Do you have a copy of the Darkmoon Field Guide, friend? It's a most useful book to carry with you.\n\nIt can help you find and identify valuable artifacts throughout your travels in Azeroth. Its detailed descriptions make it easy to decide if you've found your five hundredth brass button or that rare treasure the Darkmoon Faire's collectors crave." }
quests[29602] = { id = 29602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Gryphon Found" }
quests[29603] = { id = 29603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Provisioner Found" }
quests[29604] = { id = 29604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Saw East Temple Arrival Cinematic" }
quests[29605] = { id = 29605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brother Against Brother", description = "The Sethekk departed Skettis when Auchindoun exploded.\n\nMy brother, Syth, was one of their leaders and told us we had to go into the ruins and face our god.\n\nIn time, Syth had me cast out of the Halls for doubting them, but he refused to let me take our sister Lakka. Will you help me rescue her?", progress = "Did you find her, {name}? Was she still being held within the halls?", completion = "Knowing that Lakka is free means I can cut the rest of my ties to the Sethekk.\n\nPart of me will never forgive myself for Syth's death, but it had to be done. When I reach Skettis, I will perform the death rites for him.", objectives = "Free Lakka from captivity. Return to Isfar inside the Sethekk Halls when you've completed the rescue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29606] = { id = 29606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokk's Legacy", description = "Terokk, hero of the Arakkoa, mysteriously vanished one day, leaving only his mask and spear behind.\n\nDarkweaver Syth still holds his mask and Talon King Ikiss guards his spear.\n\nIt would mean a great deal to my people if these items were returned to us.", progress = "The relics of Terokk have been absent from Skettis for too long. Were you able to recover them from the Sethekk?", completion = "I may never truly be forgiven for my role in the crimes of the Sethekk, but perhaps by restoring the relics of Terokk to my people, I can begin to redeem myself.", objectives = "Bring Terokk's Mask and Terokk's Quill to Isfar inside the Sethekk Halls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29607] = { id = 29607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of Desire", description = "I have a buyer who is interested in the eyes of the Cobalt Serpents that have taken up residence here.\n\nIf you were to bring me some of these rare gems, I would cut you a portion of the profits.\n\nDo we have a deal?", progress = "Did you bring the eyes?", completion = "These are marvelous. Well done!\n\nHere's your cut, as promised.", objectives = "Dealer Vijad inside the Sethekk Halls wants you to bring him 3 Cobalt Eyes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29608] = { id = 29608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allies in Dalaran", description = "Welcome to Northrend, {name}. I have been asked to arrange travel for you to Dalaran so that you can meet with our allies there.\n\nRide the gryphon to Dalaran and once you land, make your way to our inn there, A Hero's Welcome. Find Isirami Fairwind and speak with her immediately.\n\nShe can help you bind your hearthstone to the city so you can use the Silver Enclave's portal to travel back to Stormwind quickly.", completion = "Welcome to Dalaran! This inn is part of the Silver Enclave, the headquarters of the official Alliance presence in our city.\n\nDon't forget to bind your hearthstone here for easy travel to the city and access to the portal to Stormwind next door.", objectives = "Accept a gryphon ride to Dalaran and speak with Isirami Fairwind at A Hero's Welcome.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29609] = { id = 29609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friends in Dalaran", description = "Welcome to Northrend. I have been asked to arrange travel for you to Dalaran so that you can meet our friends in the city.\n\nSpeak with me and accept a ride to Dalaran. Once you land, make your way to The Filthy Animal.\n\nMake contact with Uda the Beast immediately.\n\nShe can help you bind your hearthstone to the city so you can use the portal in Sunreaver's Sanctuary to travel back to Orgrimmar quickly.", completion = "I've been expecting you! This inn is part of Sunreaver's Sanctuary, the Horde's enclave in Dalaran.\n\nDon't forget to bind your hearthstone here for easy travel to the city and access to the portal to Orgrimmar, out by the fountain.", objectives = "Accept a ride to Dalaran from the flight master and speak with Uda the Beast at The Filthy Animal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29610] = { id = 29610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Player's First Arrival" }
quests[29611] = { id = 29611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Art of War", description = "Lok'tar ogar, {race}. I am Nazgrim.\n\nYou are hereby ordered to present yourself at Grommash Hold immediately.\n\nAll in service to the Horde are to swear an oath of allegiance to their new Warchief.\n\nDo not keep him waiting, {race}.", progress = "Blood and thunder, orc.", completion = "Ahh, good. You're here. And not a moment too soon...", objectives = "Speak to General Nazgrim in Grommash Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29612] = { id = 29612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Art of War", description = "Lok'tar Ogar, old friend. It has been too long since last we spoke.\n\nIt is good to see that you emerged safely from the depths of Vashj'ir.\n\nI am stationed here in Grommash Hold.\n\nAll in service to the Horde are to swear allegiance to their new Warchief.\n\nYou would do well not to keep him waiting, {name}.", completion = "Ahh, good. You're here. And not a moment too soon...", objectives = "Speak to General Nazgrim in Grommash Hold in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29613] = { id = 29613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Proper Fate", description = "Warlord Kalithresh is in charge of the entire Steamvault operation.\n\nI need you to kill him, {name}. The naga have left us with no option but violence.\n\nShow him no mercy.", completion = "I wish it had not come to this, but the naga refused all attempts to negotiate.", objectives = "Kill Warlord Kalithresh and return to Watcher Jhang inside the Steamvault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29614] = { id = 29614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Containment is Key", description = "The naga are working with leper gnomes to spread a horrific disease across Zangarmarsh. It's already spread throughout the Steamvault.\n\nClear out anything that's been contaminated and bring me the central gear from Mekgineer Steamrigger, quickly!", progress = "Be as thorough as possible. The fate of Zangarmarsh depends on it.", completion = "I'm glad we were able to contain this before it spread across all of Zangarmarsh or further. Thank you.", objectives = "Kill 3 Bog Overlords, 6 Coilfang Lepers, and obtain an Irradiated Gear from Mekgineer Steamrigger, then return to Naturalist Bite inside the Steamvault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29615] = { id = 29615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windcaller Claw and the Water Thief", description = "The Steamvault is the heart of the naga's efforts to pump the water out of Zangarmarsh, and Hydromancer Thespia personally oversees those efforts.\n\nTaking her out would seriously hinder their operation.", progress = "Did you dispatch of the water thief?", completion = "Perhaps now we can restore all of the desperately needed water to the land.", objectives = "Kill Hydromancer Thespia and return to Windcaller Claw inside the Steamvault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29616] = { id = 29616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storming the Steamvault", description = "We have not as of yet been able to stop the naga in the Steamvault, where most of their pumping infrastructure is located.\n\nThankfully, the expedition I sent there is hard at work trying to change that fact. Will you travel to the Steamvault and offer Watcher Jhang and her crew your aid?", completion = "Thank the stars you're here. We need your help!", objectives = "Speak with Watcher Jhang in the Steamvault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29617] = { id = 29617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tian Monastery", description = "People come from all over Pandaria to train at the Tian Monastery, just to the north of here. Probably because they never turn anybody down. They'll accept jinyu, hozen... or even a foreign {race} like you!\n\nMy childhood friend, Lin, just joined the monastery's order a few weeks ago. If you're interested in learning how our monks train, maybe you should go talk with her!", completion = "You've arrived at an exciting time. High Elder Cloudfall has agreed to take on a new class of trainees within the monastery. This could be my big chance to finally learn how to fight!", objectives = "Speak with Lin Tenderpaw at the Tian Monastery in the Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29618] = { id = 29618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Elder", description = "How strange, to have such a foreign-looking {class} visiting our temple. Are you here to study?\n\nYou... you look very strong. You wouldn't have any trouble getting accepted into the monastery. You should talk to the High Elder, up on the balcony above.", completion = "Welcome to Tian Monastery. I see young Lin has helped you understand the role we fill here in our hilltop village.\n\nWe are unaccustomed to outsiders. You would do us a great honor to train alongside our younglings. We do not have anything to offer you, {class}... except knowledge, and perhaps an appreciation of what it means to be pandaren.", objectives = "Speak with High Elder Cloudfall at the Tian Monastery in the Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29619] = { id = 29619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Courteous Guest", description = "I heard, I heard! The High Elder wants you to train with us!\n\nThere's going to be a banquet for us, the trainees... and you should probably bring a gift, as a sign of courtesy.\n\nThe oranges in the grove south of the temple are extra-sweet right now. Bring some back, for the banquet.", progress = "Are you ready for the banquet? I can't wait.", completion = "These will do perfectly. What a thoughtful gift, {name}!\n\nMe? I'm bringing beer, of course.", objectives = "Gather 8 Ripe Oranges from the orange groves south of Tian Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29620] = { id = 29620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Banquet", description = "The banquet should be starting any time now. Go find the High Elder and pay your respects. I'll be right behind you.", progress = "We will move on to the training soon enough, young {class}. First, we must talk, and drink, and eat.\n\nThough I must say, I admire your discipline.", completion = "That concludes our introductions. You should be ready to begin your training.\n\nThat is... you should be ready to begin your training... AFTER we have one more mug of ale. Perhaps two. Shall we, {name}?", objectives = "Speak with High Elder Cloudfall at the banquet grounds in the Tian Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29622] = { id = 29622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Training Starts Now", description = "<Xiao does not look up from his bowl.>\n\nHey, new <guy/lady>! Glad to see you survived the banquet! Trial One: Complete!\n\n<Xiao eats noisily.>\n\nYou'd better speak up with Instructor Xann. He'll be expecting you for your daily exercises.\n\n<He continues eating. You suspect that he is done talking to you.>", completion = "First, you drink too much beer... and then you show up to class late? Looks like you've already conformed to pandaren culture.\n\nLet's begin.", objectives = "Report to Instructor Xann at the Tian Monastery in the Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29623] = { id = 29623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfection", description = "Perfection can be achieved through repetition. Every single student in the training arena below will eventually perfect his or her form... assuming they don't give up first. This is a fact.\n\nI encourage you to join them, {name}. As an honorary guest of the monastery, you are not required to perform the requisite 10,000 daily strikes. Simply follow the leader's example for a few minutes.", progress = "I, too, once trained in this very arena. Times were simpler then.", completion = "This isn't your first time fighting, is it? Your form isn't perfect, but it is certainly practiced.", objectives = "Perform 12 practice strikes in the Monastery Training Arena by following the leader's example.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29624] = { id = 29624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attention", description = "Your next test also involves concentration and attention. I want you to practice your abilities on the training bags in the pit below.\n\nThe bags are hung in groups of two. When I call out \"Left\", attack the bag on the left. When I call out \"Right\", attack the bag on the right.\n\nIf you fail to follow my simple directions, this task will become much harder.\n\nNow beat on those practice bags until they burst, {name}.", progress = "What are you waiting for?", completion = "You may not be a full-time trainee here, but do not let that keep you from learning anything.\n\nI can assure you, the ability to quickly switch targets will prove valuable in future fights.", objectives = "Destroy 2 Training Bags. Follow Instructor Xann's instructions to determine which bags to attack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29626] = { id = 29626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Groundskeeper Wu", description = "We don't have many rules here, but we do have one particular rule that is worth remembering. If you want to eat...\n\n<Xiao's stomach grumbles audibly.>\n\n...you have to work. Groundskeeper Wu can give you your chores for the day. He's in the market, to the west.", completion = "<Wu addresses you sharply.>\n\n{name}, is it? The High Elder's favored son? Yes, I remember you from the banquet.\n\nDon't expect any special treatment from me, boy. You'll be working just as hard as the greenest pandaren trainee here.\n\nPerhaps harder.", objectives = "Report to Groundskeeper Wu at the Tian Monastery in the Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29627] = { id = 29627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Proper Weapon", description = "First things first, though.\n\nA proper trainee needs a proper weapon. And a scrupulous trainee builds his own... or at least gathers the materials.\n\nThe switches which grow nearby should suffice for any respectable weapon. You'll also need to shop for black walnut extract to treat the wood. While you're there, get some ale, for...\n\n<Wu pauses.>\n\n...well, you know what ale is for.", progress = "<Wu looks at you expectantly.>", completion = "<Groundskeeper Wu gratefully scoops up the gathered materials.>\n\nI will have a weapon prepared for you by the end of your training. Now, onto the real work.", objectives = "Obtain 6 Rattan Switches from the area around the market in the Tian Monastery.\n\nPurchase a vial of Black Walnut Extract from June Whiteblossom.\n\nPurchase 3 Triple-Bittered Ales from Brewmaster Lei Kanglei.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29628] = { id = 29628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strong Back", description = "Some of our trainees have... larger-than normal appetites. We have occasionally had difficulty supplying enough food for all of them. In times like these, we have to ask for help.\n\nA kindly older woman, who lives in a small house to the northwest, has agreed to make some stew for our trainees. All you need to do is go and get it.", progress = "She really is a nice woman. And an excellent cook.\n\nThe best cook in the world, actually.", completion = "I will see to it that this stew is distributed evenly and appropriately among the trainees.\n\nAfter I set some aside for myself, of course.", objectives = "Obtain a Boiling Cauldron from Mother Wu in the Waxwood Forest, then return to Groundskeeper Wu in the Tian Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29629] = { id = 29629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Steady Hand", description = "The black walnut extract you purchased from Miss Whiteblossom is but one of many extracts we keep in stock for various applications.\n\nBlushleaf extract can be gathered from the flowers in the Waxwood Forest to the west. Several units can be extracted from one flower, but only those with calm nerves and steady hands can remove all of the extract from one flower.", progress = "It is said that the ancient herbalism masters were able to remove 20 vials of extract from each blossom.", completion = "Do not forget to wash your hands. Blushleaf stains forever.", objectives = "Obtain 80 vials of Blushleaf Extract from Blushleaf Clusters in the Waxwood Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29630] = { id = 29630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And a Heavy Fist", description = "The greenwood sprites in the Waxwood Forest to the west pose no direct threat to us, this is true. However, their numbers have increased as of late, as have their wily antics.\n\nPart of our duty as wardens of this forest is to maintain the balance. Your duty is to do so by returning these sprites to the earth.", progress = "Very recently, I was walking in the Waxwood, when one of these sprites got on all fours behind my knees, evading my notice. Soon afterward, a second sprite approached me from the front, shoving me forcefully in the chest. Unaware of the first sprite, I stepped backwards, only to stumble on his prostrate form and fall, embarrassingly, onto my backside.\n\nSo yes, I have a vested interest in this assignment.", completion = "Thank you, {name}. The sprites' numbers will return in several days' time, but for now, the balance is maintained.", objectives = "Slay 10 Greenwood Tricksters in the Waxwood Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29631] = { id = 29631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Bright", description = "Might I ask a favor of you, trainee {name}?\n\nBefore I came to the monastery, I was a stranger to battle. During my time as a trainee, I performed adequately, but I was never placed in any real danger. Now, as a graduate and a wage-earning guard, I am expected to protect this perimeter at all costs.\n\nI can handle greenwood sprites, but the tigers in the western Waxwood are something different altogether. Would you mind taking care of them for me?", progress = "Please, do not speak of our arrangement with others. My cowardice shames me.", completion = "Thank you, {name}. A thousand times, thank you.", objectives = "Slay 6 Waxwood tigers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29632] = { id = 29632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Becoming Battle-Ready", description = "Alright, {race}. I'd like to see what you're really made of.\n\nYou'll find my pupils all over the monastery. Challenge them to fights. Push them to their limits. They have been instructed to do the same to you.\n\nWin or lose, you both will come out of the fight stronger.", progress = "You may be a hero in your own lands, but here, you must prove your worth.", completion = "<Master Stone Fist eyes you warily.>\n\nAlright, I've seen enough. No more beating up on the younger pupils. We will proceed to the next phase.", objectives = "Defeat 8 Tian Pupils in sparring matches at the Tian Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29633] = { id = 29633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zhi-Zhi, the Dextrous", description = "Upon the hills to my right, you will find a hozen named Zhi-Zhi. He, too, won enough sparring matches to move up the ranks. I think he will provide you with more of a challenge.\n\nChallenge him, and try to defeat him.", progress = "Zhi-Zhi's style is different than that of most pandaren monks. He and his kind tend to have more... energy... than us.", completion = "It appears that I must move you up the ranks yet again, {class}.", objectives = "Defeat Zhi-Zhi at the Tian Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29634] = { id = 29634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Husshun, the Wizened", description = "The jinyu are long-standing allies of the pandaren, and we welcome any of their kind into our monastery. Husshun, one of their elder shaman, is one of our newest trainees.\n\nHis skills as a monk are mediocre at best, but he is still a fierce combatant. He should provide you with the challenge that you deserve.", progress = "I do not know why he decided to take the monastic path so late in life. It is not my place to ask. Such questions fall under the responsibility of our Spirit-Sage.", completion = "I must warn you, {class}:\n\nIf you continue defeating my best trainees, I will no longer be able to train you. And then you will have no excuse to enjoy the presence of my company.\n\nThink wisely before you quickly dispatch any more of my students.", objectives = "Challenge and defeat Husshun at the Tian Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29635] = { id = 29635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xiao, the Eater", description = "You may have already met my best student, Xiao, at the banquet tables. I personally would have graduated him several times over, but Instructor Xann insists that he needs more discipline.\n\nIf you ask me, discipline means very little if you win every fight you enter. I'm curious to see if Xiao can keep his streak alive against you.", progress = "Young Xiao has a great future in martial arts. I wish you luck in your upcoming match.", completion = "I must admit, I was never surprised, {race}. You are a born fighter, and an excellent {class}.", objectives = "Challenge and defeat Xiao at the Tian Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29636] = { id = 29636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Test of Endurance", description = "I have taught you everything that I can, {name}. It is time you spoke with Instructor Myang.\n\nThe fights that she stages are less traditional than the sparring matches I am used to. Nevertheless, the path of a traveling adventurer like yourself is unpredictable, and a broad knowledge of fighting styles is an admirable trait.\n\nFarewell, {name}, and best of luck on the remainder of your training.", completion = "Greetings, {name}. You are becoming quite famous among the trainees here. I have already heard your name whispered several times, usually between the puffy and discolored lips one of your sparring partners.\n\nI'm looking forward to working with you.", objectives = "Report to Instructor Myang on the western side of the Tian Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29637] = { id = 29637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rumpus", description = "Master Stone Fist has trained you in the art of one-on-one combat. Now you learn the art of one-on-many.\n\nHow does fifty sound?\n\nLower yourself into the Ring of Inner Focus below, then, when you're ready, set off this firework. My assistants will come at you, several at a time.\n\nAll you need to do is survive.", progress = "Good luck, {name}.", completion = "Your {class} fighting style is strong, {name}. Our trainees could learn much from watching you.", objectives = "Set off the Monastery Fireworks in the Ring of Inner Focus, then survive the Rumpus for two minutes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29639] = { id = 29639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flying Colors", description = "You have passed every test we prepared for you, {name}. It is now time for you to move on to bigger and better things.\n\n...but not before another banquet. The High Elder will be waiting for you at the banquet grounds to celebrate your graduation from our monastery.", completion = "Congratulations, {name}. While your traineeship was strictly honorary, your results were undeniably impressive. The young ones look up to you.\n\nGroundskeeper Wu had this prepared for you. Please, use it as you see fit.", objectives = "Report to High Elder Cloudfall at the Tian Monastery in the Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29640] = { id = 29640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Spy To'gun", description = "The Shadow Council has already killed most of our spies, but To'gun was foolish enough to escape only to go back in!\n\nYou must find him. He may be reckless, but we need to find out what he knows.", completion = "Do you think you could help me get out of this cage?  It's a bit cramped.", objectives = "Locate Spy To'gun in the Shadow Labyrinth of Auchindoun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29641] = { id = 29641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soul Devices", description = "They've been torturing me, trying to get me to tell them everything that I know.\n\nThey fed the others to Hellmaw, and I was to be next. But I told them nothing!\n\nThey're using special devices to make their summoning more powerful. You must steal these devices!", progress = "Were you able to find To'gun?", completion = "So, these are the soul devices that the Shadow Council were using to enhance their summoning power?  Intriguing.", objectives = "Steal 5 Soul Devices and deliver them to Spy Grik'tha inside the Shadow Labyrinth of Auchindoun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29642] = { id = 29642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at Auchindoun", description = "I have spies within Auchindoun and they have been sending me disturbing reports.  That place has been nothing but trouble ever since it exploded a couple of years ago.\n\nSomething in there has gone horribly wrong - again - and the Shadow Council is now on a war footing.  Though the reports were lacking on details, their preparations appear to be directed inward.\n\nYou must make your way to the Shadow Labyrinth.  My field commander, Mahfuun, will fill you in on what needs to be done.", completion = "It's about time that you arrived.\n\nMehlisah said that she would be sending help days ago.  And we've been fighting in here longer than that!", objectives = "Report to Field Commander Mahfuun inside the Shadow Labyrinth at Auchindoun in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29643] = { id = 29643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Codex of Blood", description = "Two years ago the Shadow Council summoned forth a being that shattered Auchindoun in its wake.\n\nRead the Codex of Blood to find out what happened. Be warned, Grandmaster Vorpil guards it with his life.", completion = "Opening the magically-suspended tome, a sense of dread overwhelms you.\n\nSomething is most definitely wrong here!", objectives = "Read from the Codex of Blood in the Shadow Labyrinth of Auchindoun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29644] = { id = 29644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Heart of the Labyrinth", description = "The Shadow Council has lost control of the cosmic being that they summoned here almost two years ago.\n\nKnown only as Murmur, it threatens to overrun the Shadow Council and break free into the outside world!", completion = "I cringe to think what would have happened had Murmur escaped to the outside world.\n\nThank you, brave hero.", objectives = "Destroy Murmur and inform Field Commander Mahfuun inside the Shadow Labyrinth of Auchindoun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29645] = { id = 29645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambassador Hellmaw", description = "When the Cabal found our spies, they fed them to Ambassador Hellmaw one by one.\n\nOur men deserve justice. Slay the ritualists binding him, then dispose of Hellmaw.\n\nIt is a most deserving fate.", completion = "It won't bring anyone back, but at least justice has been done.", objectives = "Kill 12 Cabal Ritualists and Ambassador Hellmaw, then return to Field Commander Mahfuun inside the Shadow Labyrinth of Auchindoun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29646] = { id = 29646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flying Colors", description = "Well, I've done all that I can with you. Sounds like the others have, too.\n\nHigh Elder Cloudfall will be waiting at the banquet grounds, ready to celebrate your departure. Not that we're happy you're leaving... he just enjoys celebrations.", completion = "Congratulations, {name}. While your traineeship was strictly honorary, your results were undeniably impressive. The young ones look up to you.\n\nGroundskeeper Wu had this prepared for you. Please, use it as you see fit.", objectives = "Report to High Elder Cloudfall at the Banquet Grounds in the Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29647] = { id = 29647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flying Colors", description = "The Rumpus was your final test. You have mastered the disciplines taught at this monastery.\n\nJust as your training began with a banquet, so shall it end. High Elder Cloudfall should be waiting at the banquet grounds. I'll be right behind you.", completion = "Congratulations, {name}. While your traineeship was strictly honorary, your results were undeniably impressive. The young ones look up to you.\n\nGroundskeeper Wu had this prepared for you. Please, use it as you see fit.", objectives = "Report to High Elder Cloudfall at the Banquet Grounds in the Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29649] = { id = 29649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Save a Life", description = "Gunny is dying from a powerful curse, {name}.\n\nGrand Warlock Nethekurse augments his power with a pair of mystical braziers. If you bring me an ember from that brazier, perhaps it can counteract the dark magic?", progress = "Did you bring the ember? We don't have much time!", completion = "He was a good soldier.", objectives = "Advance Scout Chadwick inside the Shattered Halls of Hellfire Citadel wants you to bring him a Fel Ember.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29650] = { id = 29650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Ember", description = "Caza'rez is dying a coward's death.\n\nGrand Warlock Netherkurse placed a terrible curse upon him. Perhaps if you were to bring me one of the embers from his braziers, we could use it to counteract the magic before it's too late?", progress = "Did you bring the ember? Caza'rez deserves a warrior's death.", completion = "I will sing many songs of his glories.", objectives = "Stone Guard Stok'ton inside the Shattered Halls of Hellfire Citadel wants you to bring him a Fel Ember.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29651] = { id = 29651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Dying", description = "Their elite warriors are ruthless... so... powerful.\n\n<Caza'rez spits up blood.>\n\nYou have to kill them... or we will never defeat Kargath...", progress = "Are they dead, {class}?", completion = "Caza'rez...is no more.", objectives = "Caza'rez inside the Shattered Halls of Hellfire Citadel wants you to kill 4 Shattered Hand Legionnaires, 2 Shattered Hand Centurions, and 2 Shattered Hand Champions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29652] = { id = 29652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Last Favor", description = "Ol' Gunny doesn't have much longer...\n\nDo me one last favor, and kill the biggest, meanest fel orcs ye can find.\n\nFor old times' sake, aye?", progress = "Did ye kill 'em?", completion = "If only we could have saved him.", objectives = "Gunny inside the Shattered Halls of Hellfire Citadel wants you to kill 4 Shattered Hand Legionnaires, 2 Shattered Hand Centurions, and 2 Shattered Hand Champions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29653] = { id = 29653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Will of the Warchief", description = "Kargath was once one of the Horde's greatest heroes.\n\nHe now wears the false mantle of Warchief. Bring me his namesake weapon so that we can remember the champion he once was, rather than the monster he's become.", progress = "Have you proof of Kargath Bladefist's defeat?", completion = "We should not forget the orc Kargath once was, nor the lessons to be learned from his downfall.", objectives = "Bring Warchief Kargath's Fist to Stone Guard Stok'ton inside the Shattered Halls of Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29654] = { id = 29654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turning the Tide", description = "There is only one true way to end the fel orc threat to Honor Hold and the Alliance.\n\nTheir Warchief must be slain.\n\nBring me his namesake weapon, so that we can always remember his death.", progress = "Have you returned with proof of 'Warchief' Kargath Bladefist's demise?", completion = "We have struck a major blow against the enemy with your help.\n\nHonor Hold is far safer than it's been in years.", objectives = "Bring Warchief Kargath's Fist to Advance Scout Chadwick inside the Shattered Halls of Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29655] = { id = 29655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Very Special Cloth", description = "Warbringer O'mrogg has killed more brave soldiers than any enemy I've ever encountered. He is ruthless, cunning, and extremely powerful.\n\nTake him down and bring me his warcloth so that we may fashion it into a banner and show them the fury of the Horde!", progress = "Did you bring me the cloth?", completion = "Well done. This will show those blood crazed monsters what they're up against.", objectives = "Kill Warbringer O'mrogg and bring his warcloth to Stone Guard Stok'ton inside the Shattered Halls of Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29656] = { id = 29656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "O'mrogg's Warcloth", description = "Stormwind wants to see proof of our successes in the war effort.\n\nRather than showing him body bags, I thought we'd present him the warcloth of O'mrogg, Kargath's fiercest warrior. Think you can handle him?", progress = "Did you bring me the cloth?", completion = "My superiors will be very pleased to see this. Thank you.", objectives = "Kill Warbringer O'mrogg and bring his warcloth to Advance Scout Chadwick inside the Shattered Halls of Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29657] = { id = 29657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "With Great Power, Comes Great Responsibility", description = "<A voice like the sound of light bells rings in your head.>\n\nThe Mechanar employs my race's technology to create manacells, objects which provide great amounts of power.\n\nI need you to eliminate Mechano-Lord Capacitus so that Kael'thas' forces cannot harvest that power.", completion = "You have done well, {name}. But more work remains to be done.", objectives = "A'dal has asked you to slay Mechano-Lord Capacitus in the Mechanar of Tempest Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29658] = { id = 29658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Calculator", description = "<A gentle wind caresses your face.>\n\nOne more task yet remains.\n\nPathaleon the Calculator oversees many of his master's operations. He is personally responsible for much of the recent torment that has plagued this world.\n\nI ask that you eliminate him.", completion = "You have my gratitude, {name}.", objectives = "A'dal has asked you to slay Pathaleon the Calculator in the Mechanar of Tempest Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29659] = { id = 29659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Treasure", description = "I sense that one of my kind's artifacts has been taken and stashed away in the Cache of the Legion.\n\nWe cannot give them time to discover its power. If you would kill the Gatewatchers and retrieve it for me, I would be most grateful.", progress = "You've obtained it, I assume?", completion = "You have done well. Any advantage we can take away from Kael'thas' forces is to our benefit.", objectives = "Retrieve the Blinding Fury for A'dal from the Cache of the Legion in the Mechanar of Tempest Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29660] = { id = 29660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Botanica", description = "Kael'thas' forces in the Botanica were unsuccessful in handling the numerous creatures contained within. We must take action to right their wrongs.\n\nThe first step is to eliminate their forces so that they cannot cause further problems.", completion = "They were going to die to the creatures contained here soon even without our interference. It is for the greater good.", objectives = "A'dal wants you to kill Commander Sarannis, High Botanist Freywinn, and Thorngrin the Tender inside the Botanica of Tempest Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29661] = { id = 29661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lesson of Dry Fur", description = "Through meditation, I intend to find a route to locating Shu. In the meantime, you would benefit from practice and discipline.\n\nYour first task is the task of all trainees entering the pools: cross the balance poles to the west and ring the bell without falling into the pool.\n\nShould you fall, the pool's curse will make it difficult to get on a pole again, so you will need to return to the edge of the pool to start over.\n\nOh, and beware the cranes.", completion = "Good. You're a quick study.", objectives = "Cross the balance poles and ring the training bell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29662] = { id = 29662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stronger Than Reeds", description = "Gather me reeds from the nearby pools.\n\nDo not question why. Do, and then observe the results.", progress = "Telling you of my strength means nothing. I must show you.", completion = "Good.\n\nNo number of reeds have ever withstood my might.\n\nStep back, and let me dispel your doubts.", objectives = "Gather 8 Hard Tearwood Reeds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29663] = { id = 29663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lesson of the Balanced Rock", description = "I require peace to perform my meditation. Practice your arts while I meditate on Shu's location.\n\nOther monks practice balance and combat upon the balance poles in the surrounding pools. Engage them and defeat them.", completion = "Even now, your skills increase. Your footing becomes more sure. Your blows strike with more force.\n\nDiscipline and practice are the keys to reaching our full potential.", objectives = "Defeat 6 Tushui Monks atop the balance poles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29664] = { id = 29664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Challenger's Fires", description = "You're strong of mind and strong of will, but you lack the skills to face me in combat. You must fight with your body, but in truth, it is your character that is being tested.\n\nLet us even the playing field.\n\nTake this torch, light it in the brazier next to me, and then use it to light the three unlit braziers around the pool.", completion = "These fires will give you the strength that you've not yet obtained. They will illuminate your potential.", objectives = "Light your Unlit Challenger's Torch at the Brazier of Flickering Flame, then use it to light the 3 braziers near Master Li Fei.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29665] = { id = 29665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Bad to Worse", description = "After their ship crashed, evil creatures swept up from the sea to pick through the wreckage. Our aid may seem but a drop in the pond at the thought of the misfortune they've faced today.\n\nDefeat their tormentors. These people desperately need our help.", completion = "You are a fear to behold upon the battlefield.", objectives = "Defeat 8 Deepscale Tormentors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29666] = { id = 29666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sting of Learning", description = "There are dangers in the pools. The latest and most vicious are the water pincers. A time has come for their numbers to be diminished, and I am no longer up to the task.\n\nIf you could clear out some of the water pincers, I would be very appreciative. Beware their numbers... sometimes it's best to lure them from the pool-side rather than wading all the way in.", completion = "The water pincers are strange creatures. They seem to be drawn to still water.", objectives = "Kill 6 Water Pincers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29667] = { id = 29667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Herd", description = "It seems that Kael'thas' forces have twisted the Botanica's specimens beyond saving. I do not want to see them unleashed upon Outland as so many others have.\n\nThere is one, Laj, who I would like to examine. He is different somehow. Perhaps we can learn from him.", progress = "I see you have obtained the frond. Very good.", completion = "You have done well thus far, {name}. However, there is still one more task I must ask that you complete.", objectives = "A'dal has asked you to kill 6 Mutate Fleshlashers, 6 Mutate Fear-shriekers, 6 Mutate Horrors, and to obtain a Rapidly Evolving Frond from Laj in the Botanica of Tempest Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29669] = { id = 29669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Most Somber Task", description = "I must now ask you to complete a most somber task.\n\nWarp Splinter used to act as guardian to all of the Botanica. He is now impure, and must be taken down.", completion = "He was a noble guardian in life. His presence will be missed.", objectives = "A'dal has asked you to slay Warp Splinter in the Botanica of Tempest Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29670] = { id = 29670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maul Gormal", description = "Thanks to you, there's a small militia of farmers hiding nearby. Hanae said something about giving them \"liquid courage\" which, I'm pretty sure, means they're sauced and ANGRY.\n\nThe mogu think they can walk all over us - we'll give them a fight that will open their eyes.\n\nFollow the trail through the ruins and down to the beach. Find their leader. When you engage him, we'll be there to back you up.", progress = "We are ready to fight the mogu leader whenever you are.", completion = "This is extremely unsettling. If mogu are banding together like this all over the continent, it could become a major threat to Pandaria.", objectives = "Kill Subjugator Gormal in Camp Gormal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29671] = { id = 29671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Morass", description = "The Infinite Dragonflight have abandoned all pretense of subtlety. They plot to destroy the Guardian, Medivh, and prevent the Dark Portal from ever opening. While outwardly, this may appear a boon to the forces of the Alliance, it is in actuality catastrophic and will result in your world ending.\n\nYou must venture through the timeway leading to the Black Morass. Go west and then south, past my future self, until you reach the tunnel that houses the swamp specimens. Cross over and speak with Sa'at.", sourceObjective = "Travel through the Caverns of Time to the Black Morass during the opening of the Dark Portal and speak with Sa'at.", sourceObjectiveStatus = "unverified-source-field" }
quests[29672] = { id = 29672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Opening of the Dark Portal", description = "Here the Guardian Medivh feverishly works to open the Dark Portal.\n\nScattered across the morass, rifts will materialize. Infinite will pour out of the rifts and attempt to destroy Medivh's shields and, ultimately, Medivh.\n\nKill their rift lords and leaders until Medivh succeeds!You will be able to choose one of these rewards:", objectives = "Sa'at inside the Black Morass of the Caverns of Time has tasked you with defending Medivh until he succeeds in opening the Dark Portal.\n\nReturn to Sa'at should you succeed in your task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29673] = { id = 29673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Morass", description = "The Infinite Dragonflight have abandoned all pretense of subtlety. They plot to destroy the Guardian, Medivh, and prevent the Dark Portal from ever opening. While outwardly, this may appear a boon to the forces of the Alliance, it is in actuality catastrophic and will result in your world ending.\n\nYou must venture through the timeway leading to the Black Morass. Go west and then south, past my future self, until you reach the tunnel that houses the swamp specimens. Cross over and speak with Sa'at.", sourceObjective = "Travel through the Caverns of Time to the Black Morass during the opening of the Dark Portal and speak with Sa'at.", sourceObjectiveStatus = "unverified-source-field" }
quests[29674] = { id = 29674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbound Darkness", description = "<The sound of chimes enters your head, but it is distressed.>\n\nWe imprisoned the most dangerous beings we came across in our travels.\n\nZereketh is a powerful void lord. If he escapes into Netherstorm, he will feed off of the abundant void energy.", completion = "Creatures of the void are naturally chaotic. They are a necessary part of the universe, but they must be kept in check by the Light.", objectives = "A'dal has asked you to slay Zereketh the Unbound in the Arcatraz of Tempest Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29675] = { id = 29675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hey There Dalliah", description = "Two powerful agents of the Burning Legion, Wrath-Scryer Soccothrates and Dalliah the Doomsayer, have begun rallying the demons on board together into a small army.\n\nYou cannot let their forces grow any larger, or the Arcatraz may soon become yet another Legion stronghold.", completion = "The Legion seeks only to consume. They hold no regard for the balance.", objectives = "A'dal has asked you to kill Wrath-Scryer Soccothrates and Dalliah the Doomsayer in the Arcatraz of Tempest Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29676] = { id = 29676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding an Old Friend", description = "It seems Shu, the spirit of water, had a play companion when he came to the pools throughout the years. An old pandaren we know as Old Man Liang.\n\nLiang moved away from the main town and stopped practicing in the pools some time ago. I am told he lives in a small house northeast of here, up the hill.\n\nLiang may know what has driven Shu away, and where the spirit might be found.\n\nGo to Liang. Ask of Shu.", completion = "Visitors are rare up here, but you are welcome. It is nice to meet you, young {class}.", objectives = "Speak to Old Man Liang at Liang's Retreat in the Singing Pools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29677] = { id = 29677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sun Pearl", description = "Shu, the spirit of water, is eternally young, as are all the spirits of Shen-zin Su. I have been friends with Shu all of my life, but I no longer have it within me to play with him. I am old, and lack the energy.\n\nFor all his complexities, Shu is simple to please: he desires friendship. When I returned to play with Shu each season, I would always bring a Sun Pearl as a gift, and then we would play together. You can find a Sun Pearl in the pools to the southeast. Perhaps you can be his new friend.", progress = "The decision to not return to the pools was a hard one. I don't think Shu ever truly understood. He does not know what it is to get older and weaker.", completion = "Shu's desires are not so different from our own. He does not want to be alone. Unwanted, unloved. He longs to be needed, and to share his life with others.\n\nKnowing that, earning his trust is not terribly difficult. He just wants company.", objectives = "Retrieve the Sun Pearl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29678] = { id = 29678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shu, the Spirit of Water", description = "Shu, the spirit of water, is sulking in the deep pool to the north. Cross the rocks and then drop the sun pearl in the center of the pool. He will know what this means.", objectives = "Coax Shu, the spirit of water, into a game.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29679] = { id = 29679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Friend", description = "He wants you to play with him. Go for it!", progress = "This is your task, {class}. See it through.", completion = "I have to admit, that looked pretty fun from my angle.\n\nAnd you seem to have made a new friend.", objectives = "Water walk into 5 of Shu's Water Spouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29680] = { id = 29680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Source of Our Livelihood", description = "We have done as Master Shang asked of us. I will return to the temple to inform the master of our progress. You should continue south on the road to the farmlands to seek out Wugou, the spirit of earth.\n\nJi awaits you at the Dai-Lo Farmstead, and he'll surely need your help. I must warn you, Ji can be reckless in his directness. Remember well the things I have taught you: discipline and patience.", completion = "{name}! I wondered when I would see you again!\n\nWell, the plus side is that finding Wugou, the spirit of earth, was easy enough. Waking him... not so much. I think he's going to wake quite sore from all the pushing and hitting I've done trying to rouse him.", objectives = "Speak to Ji at the Dai-Lo Farmstead. A cart is waiting near the road to take you there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29681] = { id = 29681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maximum Security Breakout", description = "Harbinger Skyriss is the heart of the problem in the Arcatraz.\n\nHe corrupted Warden Mellichar and made him release many of the prisoners. It is only a matter of time before the Harbinger himself is let loose.\n\n{name}, you cannot let a servant of the Old Gods live!", completion = "Thank you, {name}. Your actions this day have prevented countless tragedies.", objectives = "A'dal has asked you to slay Harbinger Skyriss in the Arcatraz of Tempest Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29682] = { id = 29682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magisters' Terrace", description = "We recently sent in an expeditionary force to the Magisters' Terrace to stop the Legion forces there.\n\nHowever, we haven't heard from them since, and I fear the worst.\n\nWill you go there and try to find Exarch Larethor? He's in charge of the expedition.", completion = "Dawnhearth thought we were dead? Hah!\n\nI haven't sent a report because we haven't made any progress past this point.\n\nPerhaps you can help us change that?", objectives = "Captain Theris Dawnhearth wants you to find Exarch Larethor inside the Magisters' Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29683] = { id = 29683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scryer's Scryer", description = "<Tyrith winces in pain as he speaks.>\n\nGo to the terrace... use the orb.\n\n...They're...feeding the sunwell....\n\n <Tyrith gasps for breath.>\n\nHurry... They must be stopped... before they can....\n\n<Tyrith dies.>", objectives = "Tyrith wants you to use the orb on the balcony in Magisters' Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29684] = { id = 29684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Severed Communications", description = "We've had a contact embedded in Magisters' Terrace gathering intelligence for us for some time now, but we've lost contact with him.\n\nThe information he was collecting is vital to our mission.", completion = "...Come closer, {race}... Listen carefully to my words....", objectives = "Exarch Larethor inside the Magisters' Terrace wants you to find Tyrith, a blood elf spy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29685] = { id = 29685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hard to Kill", description = "As you've now witnessed, the Legion forces work tirelessly, manipulating the Sunwell's power to achieve their malevolent ends.\n\nKael'thas has risen from the ashes of defeat and once more leads them in their efforts. He must be stopped.", progress = "Well, {class}, I must admit, I wasn't sure I'd see you again.", completion = "<Larethor listens intently as you explain your deeds in Magisters' Terrace.>\n\nTyrith will be missed - good man, that one. Thanks to you though, his death wasn't in vain.", objectives = "Kalecgos has asked you to defeat Kael'thas in Magisters' Terrace. You are to take Kael's head and report back to Larethor inside the Magisters' Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29686] = { id = 29686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Radical Notion", description = "We cannot afford to lose this war. I'd like to empower our sentries so that brave men and women don't have to die.\n\nThe Legion has gotten a hold of a powerful elemental being. Its essence could be just what we need.", progress = "Were you able to get your hands on its essence?", completion = "Excellent! I can't wait to present this project to my superiors!", objectives = "Exarch Larethor in the Magisters' Terrace wants you to kill Vexallus and obtain its essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29687] = { id = 29687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twisted Associations", description = "The Legion and Kael'thas' forces are becoming increasingly intertwined. This concerns me very deeply.\n\nFrom what we can gather Selin Fireheart and Priestess Delrissa work closely together to unite the two armies. You need to stop them.", completion = "Well done, soldier. One step at a time.", objectives = "Exarch Larethor in the Magisters' Terrace wants you to kill Selin Fireheart and Priestess Delrissa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29688] = { id = 29688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Advancing the Campaign", description = "I mostly listen, {class}. I listen so that the Warchief doesn't have to.\n\nI've heard of the status of our campaign against the Hellfire Citadel. It is time to take the Shattered Halls, seat of power for the fel orcs.\n\nGo speak with Stone Guard Stok'ton, he's in charge there.", completion = "Keep your head down, or it's likely to end up on the wrong end of an arrow.", objectives = "Shadow Hunter Ty'jin has asked you to speak with Stone Guard Stok'ton inside the Shattered Halls of Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29689] = { id = 29689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Advancing the Campaign", description = "The time has come to lay the final blow against the fel orcs.\n\nAdvance Scout Chadwick awaits your presence inside the Shattered Halls of Hellfire Citadel. Make haste, their forces could strike against Honor Hold at any moment!", completion = "Be quiet! We'll surely be overwhelmed if they notice us now.", objectives = "Force Commander Danath Trollbane has asked you to speak with Advance Scout Chadwick inside the Shattered Halls of Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29690] = { id = 29690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Mists", description = "<Nazgrim fills his lungs with sea air.>\n\nYou smell that, {name}? It's the smell of our home, the lands our kind have bled and died to preserve.\n\nAnd listen... you hear that? It's the sound of peace and safety - a haven we've carved, where our enemies fear to tread.\n\nRemember these things. You won't experience them again anytime soon. We have ourselves a war to win.\n\nNow go get settled, we're shovin' off!", completion = "{name}!?\n\nThey told me you were dead...\n\nI'm glad to see it wasn't true. There's Alliance to kill!", objectives = "Speak to General Nazgrim on Hellscream's Fist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29691] = { id = 29691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Me A Shrubbery!", description = "My people use sanguine hibiscus for a number of purposes.\n\nIt grows naturally only in the Underbog, and many of the bog's denizens have taken a liking to it.\n\nIf you could bring me some, I would be very grateful.", progress = "Were you able to gather any hibiscus?", completion = "These will do nicely, but we can always use more.  Perhaps you will find yourself in the Underbog again soon?", objectives = "Collect 5 Sanguine Hibiscus and return them to T'shu in the Underbog.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29692] = { id = 29692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Me Another Shrubbery!", progress = "We can still use more sanguine hibiscus. We're always struggling to find more.\n\nBring them to me in bunches of five and I will be most grateful.", completion = "These will do nicely, but we can always use more.  Perhaps you will find yourself in the Underbog again soon?" }
quests[29693] = { id = 29693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The General's Edge", description = "As you gradually gather your senses and begin to take in your surroundings, this object stands out amongst the strewn wreckage.\n\nIt occurs to you that this is the first time you've seen Nazgrim's axe outside of his tight grasp. Somehow, this fact makes your predicament even more unsettling...\n\nYou know that dead or alive, the General would want his weapon back in his possession.", objectives = "Bring Nazgrim's axe to General Nazgrim.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29694] = { id = 29694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regroup!", description = "They have an airbase! I have underestimated this Alliance Captain for the last time. So many good warriors lost...\n\nThere must have been a few survivors who were able to bail during the crash. We need every able-bodied fighter we can get.\n\nFind as many survivors as you can in the forest below, and I will investigate the wreckage itself. Rally everyone together at the nearby village for a counter-attack.", progress = "Did you find any survivors?", completion = "These are the only survivors, {name}?\n\nSo be it. We will play the hand fate has dealt us.\n\n\n\nNumbers be damned. This is where heroes are made.", objectives = "Rescue Shademaster Kiryn, Rivett Clutchpop, Shokia, and Sergeant Gorrok from Honeydew Glade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29695] = { id = 29695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kiryn TRACKING" }
quests[29696] = { id = 29696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Stars!", description = "A number of Kiryn's articles have been scattered around the area by wood sprites, but this one stands out as important to you.\n\nThe bag once hung from her waist, loaded with throwing stars. Without them, her arsenal will be considerably diminished.\n\nIf you were to retrieve the weapons from the pests that inhabit this region, it could only help your cause.", objectives = "Collect 100 of Kiryn's Throwing Stars from Devious Wood Sprites.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29697] = { id = 29697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rivett TRACKING" }
quests[29698] = { id = 29698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Alliance Banner Found" }
quests[29699] = { id = 29699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Alliance Chest Found" }
quests[29700] = { id = 29700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Bodyguard Found" }
quests[29701] = { id = 29701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Journal Found" }
quests[29702] = { id = 29702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorrok TRACKING" }
quests[29703] = { id = 29703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barrel of Monkies", description = "These monkeymen are driving me insane!  I was just trying to get some insight into panderan brewing tactics and these hozu things keep drinking the brews before I can properly chemical test them.  Can you please go take a few of them out as a lesson to the others?  I'll make it worth your while.", objectives = "Sally Fizzlefury wants you to kill 5 drunken monkies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29704] = { id = 29704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shokia TRACKING" }
quests[29705] = { id = 29705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion of the Bottle Snatchers", description = "As if the hozu weren't enough now we have a bunch of renegade dwarven brewmaster wannabes floating around.\n\n Can you please recover the brewskies they stole? It would cripple the Ironforge economy if this many \"entrepreneurs\" started popping up.", objectives = "Sally Fizzlefury wants you to recover 5 stolen brewskies from the Brewhunters near the farm in Shen-zin Su.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29706] = { id = 29706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kegplosion", description = "Oh no {class}!  In what can only be described as a contrived act of contention, the nearby spirit walkers have become enraged.\n\nPlease do something about them before they eat our faces!", objectives = "Kill 5 Enraged Spirit Walkers before they eat Sally Fizzlefury's face.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29707] = { id = 29707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Opened Shackle 1" }
quests[29708] = { id = 29708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Opened Shackle 2" }
quests[29709] = { id = 29709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Opened Shackle 3" }
quests[29710] = { id = 29710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Looted Food Crate" }
quests[29711] = { id = 29711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Looted Scroll" }
quests[29712] = { id = 29712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horde Justice", description = "Your mind races as you struggle to come to terms with your predicament - shipwrecked on an uncharted land, nearly all of the crew lost....\n\nAs you look at the corpse of this unfortunate creature you realize that the area is crawling with his kind, and that they're pillaging whatever supplies haven't been destroyed.\n\nIt's time to introduce these vermin to some good old-fashioned Horde justice.", objectives = "Kill 15 Hozu at the Wreck of the Sky Shark.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29713] = { id = 29713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standard Protocol", description = "The Sky Shark has been totally destroyed.\n\nWith Alliance forces about, standard protocol requires the destruction of any sensitive technologies. These solenoids most certainly fall under that category.\n\nThe Horde's directives are clear, round up the solenoids for destruction.", objectives = "Gather 8 Unstable Solenoids.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29714] = { id = 29714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wet Work!", description = "If any Alliance naval forces have come ashore, the smoky fires from your crash will lead them right to you and what remains of your crew.\n\nThere must be a way to extinguish those flames...\n\nThis barrel seems to have survived the catastrophe intact. Perhaps it's still water-tight.\n\nOnly one way to find out!", objectives = "Collect 5 Water Globules from Spiritsong Lake and combine them with the Horde Barrel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29715] = { id = 29715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Witch in the Woods", description = "Oh please {race}!  Can you help me?\n\nSome of the village children were playing in the woods and haven't come back. Could you please keep an eye out for them if you are going out there?\n\nI told those village rascals to leave that old widow up in the woods alone. My guess is they are probably harassing her. They think she is a witch.", sourceObjective = "Find An Windfur on the road north of the Jade Witch Hut.", sourceObjectiveStatus = "unverified-source-field" }
quests[29716] = { id = 29716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Double Hozen Dare", description = "There is a witch in the woods but no one believes me. She turned my friend Shin into jade!\n\nWe were all so scared we tried to run back but she sicced her big jade monsters on us. A bunch of my friends tried to get away by climbing trees.\n\nCan you help me save my friends?", progress = "Where is Shin? I didn't see Shin.", completion = "Oh thank you so much for helping find my friends.  I still don't see Shin though...", objectives = "Rescue 6 Scared Pandaren cubs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29717] = { id = 29717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down Kitty!", description = "I tried to fight one of the jade tigers in the woods but they were too scary. They stare at you and you turn to a jade statue!\n\nHonest truth! Chen's sister's friend Ni heard it from Kai's mom.\n\nI want to be brave like you though. Can you show me how to beat up those jade tigers?", progress = "Wow! You are tough!", completion = "Wow! You were awesome! You were like *bam* and they were like *aaaaa* and then they were smashed!", objectives = "Destroy 8 Jade Guardians.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29718] = { id = 29718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sixteen Fluid Ounces of Prevention", description = "Better safe than sorry.\n\nThe pillars of smoke surrounding the crash site will be a beacon to any Alliance who might have seen your Zeppelin in distress.\n\nUntil you and your depleted crew get your bearings, you could do without that kind of trouble.\n\nExtinguishing the wreckage fires is just plain common sense.", objectives = "Use the Spirit-Touched Water Barrel to extinguish the four fires near the Zeppelin Wreckage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29719] = { id = 29719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Double Hozu Dare", description = "Shin is still missing!\n\nI never... I mean the other kids never should have double hozu dared him to knock on the witch's door. \n\nWe saw a bunch of jade statues south of the Jade Witch's hut. \n\nCan you come with me and see if any of them are Shin?", objectives = "Inspect 7 Lifelike Jade Statues south of the Jade Witch Hut.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29720] = { id = 29720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Jade Witch", description = "The Jade Witch must still have Shin.\n\nI... I can't do it!  I don't want to see the witch.  Can you please go talk to her?  You're an adult.  I don't think she would turn you into jade.", sourceObjective = "Speak with the Widow Greenpaw at the Jade Witch Hut.The Jade Witch must still have Shin.\n\nI... I can't do it!  I don't want to see the witch. Can you please go talk to her?  You're an adult. I don't think she would turn you into jade.", sourceObjectiveStatus = "unverified-source-field" }
quests[29721] = { id = 29721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Offering", description = "Well young one, if you would do me a kindness before I help.  \n\nBehind my hut is a small pond.  I keep a stock of very rare fish that I need for ritual.  It was a favorite of my late husband.\n\nCould you please bring me one?", sourceObjective = "Widow Greenpaw has asked for you to bring her a fish from the pool behind the Jade Witch's Hut in the Jade Forest.Well young one, if you would do me a kindness before I help. \n\nBehind my hut is a small pond. I keep a stock of very rare fish that I need for ritual. It was a favorite of my late husband.\n\nCould you please bring me one?", sourceObjectiveStatus = "unverified-source-field" }
quests[29722] = { id = 29722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Bravery", description = "Can you help teach me to be brave like you?\n\nWhen we played our prank on the witch we made a bunch of Leafy Tricksters angry.  I think the witch did something to them.\n\nCan you show me how you stand up to them?", objectives = "Defeat 8 Leafy Tricksters south of the Jade Witch Hut.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29723] = { id = 29723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Jade Witch", description = "The Jade Witch must still have Shin.\n\nI... I can't do it! I don't want to see the witch. Can you please go talk to her and see if she has Shin?\n\nYou're an adult, I don't think she would try to turn you into jade.", completion = "Hurray! Thank you so much! Shin is saved and you beat up the old witch! And the best part is our parents were never told what we were up to. Hurray!\n\nIt looks like everybody who came back are trying to get rid of whatever jade they had. Toya's been collecting it for some reason and said you should go chat with him.", objectives = "Defeat the Jade Witch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29724] = { id = 29724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burial at Sea", description = "These savages are... ruthless.\n\nThey've dragged off our dying soldiers to be tormented in their camps. This is no way for our valiant brothers to die.\n\nI shall join them soon enough, {class}. Please, put my mind at ease and their bodies to rest.\n\nFind their remains at the camps surrounding the wreckage. Put them out of the reach of these creatures.", objectives = "Bring the 3 Vanguard Corpses to the Immobile Catapult at the Wreck of the Sky Shark.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29725] = { id = 29725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SI:7 Report: Fire From the Sky", description = "Yeah, we found Amber, she's alive, and all that. That's about where the good news stops though.\n\nLet's see if I can pick up where ol' Rell left off...", progress = "I'm not done with the report yet, {name}. Settle down.", completion = "So, now you know why ol' Rell's all beat up.\n\n<You detect a change in Sully's facial expression, and he quickly turns away. Is he... crying?>", objectives = "Listen to Sully's report.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29726] = { id = 29726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SI:7 Report: Hostile Natives", description = "I... I can tell you what happened next! We continued north, into the forest...", completion = "Luckily, we all made it out alive.\n\nWell... all of us except for Socks...", objectives = "Listen to Little Lu's report.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29727] = { id = 29727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SI:7 Report: Take No Prisoners", description = "The final leg of our journey took us west, to a large hozen village. We set up a small camp in the mountains, outside of their line of sight...", progress = "Please, allow me to finish.", completion = "So there you have it. We didn't find the White Pawn, but we came back with intel that could be of even greater importance to the Alliance.\n\nThe Horde have allied with the hozen, and are arming them as we speak. They and their monkey army now outnumber us thirty to one.", objectives = "Listen to Amber Kearnen's report.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29728] = { id = 29728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Evidence", description = "I must ask you to do one more thing for me, {name}.\n\nThe personal effects on this ship cannot be left for others to find. We'll have to destroy it.\n\nI cobbled together some Makeshift Dynamite from the scraps you brought me.\n\nPlace the dynamite anywhere on the ship, but take care not to put them too close together.\n\nThey might be...uh...a little unwieldy, so you should spread them out in case of premature detonation.", objectives = "Plant 4 Makeshift Dynamite near the sunken ship at Sapphire's End. Makeshift Dynamite must be placed at least 10 yards apart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29729] = { id = 29729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Without a Trace", description = "The explosives are set. All we have to do now is pull the trigger.", objectives = "Press the detonator to erase the remaining evidence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29730] = { id = 29730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting Report: Hostile Natives", description = "I bet I know your first question: \"What the ook happened to Sergeant Gorrok?\" Don't worry, don't worry. He's totally alive. Not dead or anything.\n\n<Riko shuffles uncomfortably.>\n\nWell, we THINK he's alive, but he ALSO might be very, very dead.\n\n<Riko looks into your eyes for approval.>\n\nFine! Let me tell you exactly what happened.", progress = "I'm not ookin' done yet!", completion = "So, as you can see, none of this is Riko's fault.", objectives = "Listen to Riko's report.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29731] = { id = 29731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting Report: On the Right Track", description = "MOST of what Riko said is true.\n\nWe didn't dare pursue Gorrok - the Horde's numbers here are far too few. Our forces can only sustain so many losses, and frankly, we don't know how powerful that witch really is.\n\nLet me pick up where the hozen left off...", progress = "If I may continue, please?", completion = "And that's how we found our Alliance captive.\n\nBut that's not all that happened. Not by a long shot...", objectives = "Listen to Kiryn's report.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29732] = { id = 29732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Goes Down, Must Come Up!", description = "Rivett left behind what looks to be an important piece of equipment. Along its shaft you are able to make out the words: Goblin Drone Dispenser.\n\nWith a simple calibration, the device is set to deliver drones to Nazgrim's basecamp.\n\nEasy enough....\n\nThere's just one problem. The only supply crates worth transporting have fallen to the cliff ledge below the crash impact.\n\nAs you ponder the issue, you see the long, coiled tail of a Cliff Glider fly by the corner of your eye...", objectives = "Use the Goblin Drone Dispenser near the Exposed Root to recover supplies.\n\nNOTE: Each use will require one Cliff Glider Tail.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29733] = { id = 29733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SI:7 Report: Lost in the Woods", description = "<Rell coughs heavily before speaking.>\n\nPlease, {name}. You need to hear what we've been through.\n\nThe whole damned Alliance needs to hear what we've been through. There may not be much time left.", progress = "<Rell doesn't look too good. He should probably save his energy.>", completion = "...and that's <cough> how we found...\n\n<Rell's speech devolves into heavy coughing. The corner of his mouth produces a trickle of blood.>", objectives = "Listen to Rell's report.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29734] = { id = 29734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deepforge the Elder", objectives = "Your spirit burns with life, young {class}.  I accept the homage you pay, and offer in return this token...", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29735] = { id = 29735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stonebrand the Elder", objectives = "Your spirit burns with life, young {class}.  I accept the homage you pay, and offer in return this token...", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29736] = { id = 29736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkfeather the Elder", objectives = "Your spirit burns with life, young {class}.  I accept the homage you pay, and offer in return this token...", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29737] = { id = 29737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firebeard the Elder", objectives = "Your spirit burns with life, young {class}.  I accept the homage you pay, and offer in return this token...", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29738] = { id = 29738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonlance the Elder", objectives = "The heavens, in their countless stars, hold answers to earthly mysteries, {name}.  Might, then, the wise, and the lucky, gaze up and find truth?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29739] = { id = 29739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windsong the Elder", objectives = "The heavens, in their countless stars, hold answers to earthly mysteries, {name}.  Might, then, the wise, and the lucky, gaze up and find truth?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29740] = { id = 29740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evershade the Elder", objectives = "The heavens, in their countless stars, hold answers to earthly mysteries, {name}.  Might, then, the wise, and the lucky, gaze up and find truth?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29741] = { id = 29741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sekhemi the Elder", objectives = "All tol'vir were once as I am. Now, my people are flesh and blood, and more in need of the wisdom of the ages than ever before.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29742] = { id = 29742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Menkhaf the Elder", objectives = "All tol'vir were once as I am. Now, my people are flesh and blood, and more in need of the wisdom of the ages than ever before.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29743] = { id = 29743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monstrosity", description = "It's plain to see that this statue and the surrounding ruins are of ancient origin. Clearly, this land has a deep history, which means it could not have been born of the cataclysm.\n\nAnd yet these waters have been explored for ages now, with no record of anything here but open sea.\n\nPerhaps if you were to sketch the pieces of this broken statue, you might shed light on the continent's origins.", objectives = "Collect sketches of each piece of the ancient statue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29744] = { id = 29744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some \"Pupil of Nature\"", description = "Wood sprites are not prone to wandering, so I'm surprised they ventured down as far as the mason's quarter. Something must be forcing them out of their natural habitat.\n\nThese particular sprites are native to the Woods of the Lost, just north of here. I'd go myself, but I've heard those woods are haunted.\n\nSo yeah, that's out.\n\nI guess we'll never know.\n\n<Weng coughs.>\n\nOrrrr... A big brave adventurer like YOU could go check it out! What do you say?", objectives = "Investigate the Woods of the Lost, northeast of the Greenstone Quarry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29745] = { id = 29745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sprites' Plight", description = "<Living statues rampage through the woods.\n\nFor now, they seem content in pummeling the forest sprites into splinters, but if they continue any further the pandaren will have more than just missing jade to worry about.>", objectives = "Slay 10 Stonebound Destroyer the Woods of the Lost and discover their source.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29746] = { id = 29746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breadcrumb Into Ruins", description = "The spirits released from these statues are being pulled--rather violently--toward the coastal ruins up ahead.\n\nIt seems unlikely that they'll be allowed to rest...", objectives = "Head into the Ruins of Gan Shi, northwest of the [JADE MINES].", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29747] = { id = 29747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break the Cycle", description = "<Mogu conjurers call forth hapless spirits from beyond, forcing them into statues.\n\nIt seems that destroying the statues alone will not be enough to break the cycle.>", objectives = "Kill 8 Shan'ze Spiritbinders in the Terrace of Ten Thunders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29748] = { id = 29748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simulacrumble", description = "<The shattered remains of an ancient mogu statue. This one looks like it never animated before it was broken.\n\nWhatever dark magic the mogu are employing here, it seems to make the brittle statues significantly tougher. Better to destroy them while they are still vacant.\n\nA good old-fashioned kick should do the job.>", objectives = "Kick 6 Vacant Destroyers in the Terrace of Ten Thunders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29749] = { id = 29749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Urgent Plea", description = "<Your mind is racked with a howl. Beneath it, a wispy voice is barely audible, as if from far away.>\n\nPlease... help... heart of the ruins... a ritual... conjuring...\n\n...should not be here...\n\nMy staff... on the altar... take it. Please hurry.", progress = "Spirit-binding! How can the mogu have been allowed to resume such a disgusting practice?! And now here I am, the product of a half-failed conjuring...\n\n<The spirit fumes for a moment, then turns to you.>\n\nWhat century is this?", completion = "Allow me to introduce myself: I am Pei-Zhi, Master Spiritsage under the last pandaren emperor Shaohao.\n\nAt least... I was.", objectives = "Recover the Staff of Pei-Zhi and interrupt the mogu ritual in the center of the Terrace of Ten Thunders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29750] = { id = 29750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vessels of the Spirit", description = "The Spiritclaws are a sect of mogu assassin-priests who, at the height of the mogu empire, were the most elite and most feared of the emperor's troops.\n\nAll have mastered a deathblow which ensnares the spirit of the enemy, trapping it in a jade bottle for delivery to a Spiritbinder.\n\nIf you encounter any Spiritclaws further ahead in the ruins, take note: their belts hang with a cursed weight.\n\nRelieve them of their burden and bring the bottles back to me.", progress = "To think the mogu have continued training the Spiritclaws for all these years...\n\nDid you get the bottles?", completion = "Thank you, {class}.\n\nI can already sense the spirits within these bottles - they cry out with fear, confusion... rage.", objectives = "Recover 8 Spirit Bottles from Shan'ze Spiritclaws in the Terrace of Ten Thunders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29751] = { id = 29751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Artifacts", description = "So many spirits held in captivity here... I can feel them everywhere. Even the walls are a cage for the long-dead.\n\n{name}, we cannot simply break the sorcery over this place - doing so would release countless agonized souls to wander the earth. They will need a beacon, something to guide them.\n\nWith your help, I can create a tan-chao: a bridge from this world to the heavens. For this ritual, I'll need a bowl, a candle, and a jade cong. You should be able to find them all within the ruins.", progress = "Have you found the items we need for the ritual? We cannot guide these spirits back without them.", completion = "Good work. With these, I can complete the ritual to send all of the spirits here--including myself--back where they belong.", objectives = "Bring Pei-Zhi a Chipped Ritual Bowl, a Pungent Ritual Candle, and a Jade Cong from the Terrace of Ten Thunders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29752] = { id = 29752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wayward Dead", description = "The process of mass conjuring, as the mogu are doing here, is not without byproduct. Some spirits arrive too distraught or unruly to be harnessed, so they are confined and left to wander until their desperation leaves them more malleable.\n\nI suspect the mogu have such a holding area somewhere nearby, likely guarded by spiritclaws.\n\nPlease, take my staff again and use it to collect these wayward spirits. You needn't fight them - present the staff and they should be drawn in.", completion = "Thank you, {name}. I will take them with me into the nether.", objectives = "Use the Staff of Pei-Zhi to absorb 10 Wayward Ancestors in the Terrace of Ten Thunders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29753] = { id = 29753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Nature", description = "I'm afraid I have another favor to ask, {name}.\n\nThe bottles you recovered contain neither the spirits of mogu ancestors nor recently slain foes; they contain spirits of beasts. It seems the spiritclaws have resorted to poaching in an effort to fuel their simulacra.\n\nThis complicates our task, for I cannot take the beasts with me through the bridge.\n\nTake the bottles west to Tideview Thicket and smash them to return the spirits to nature. Some may be blind with rage and will need to be subdued.", progress = "Do not fear for the spirits of the beasts - they will find peace here.", completion = "Their bodies had long since returned to the land - their spirits can now follow.", objectives = "Throw Spirit Bottles on the ground in Tideview Thicket to release 8 Beast Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29754] = { id = 29754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Bridge Earth and Sky", description = "We are ready to open the tan-chao and guide all of these spirits back to peace.\n\nIf I may, I would have your assistance once more. The mogu will surely sense the ritual taking place and will do everything in their power to halt it. I need only a few moments without interference, and once the path is open it will surge too greatly to be closed.\n\nIf you are willing to help one more time, please accompany me to the ritual site.", objectives = "Protect Pei-Zhi during his ritual at the Terrace of Ten Thunders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29755] = { id = 29755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pei-Back", description = "<Ancestral spirits stream into the tan-chao, Pei-Zhi's bridge to freedom.\n\nOne final chamber lingers in the ruins, just north of the tan-chao. The air above crackles with foul energy. Shan Jitong is already at work.>", completion = "This age must be one of great strife to breed heroes such as you. I can only imagine what adventures must lie ahead.\n\nIt has been my great honor to have met you, {name}.\n\nI will remain here to usher out the last of the spirits before crossing the tan-chao myself.\n\nStill, I am disturbed by the spirit waker's dying curse...\n\n\"You will not stop the thunder.\"\n\nWhat could he have meant?", objectives = "Confront Shan Jitong and rescue Pei-Zhi at the Seat of the Spirit Waker in the Terrace of Ten Thunders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29756] = { id = 29756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Humble Offering", description = "I'm almost ready for the ritual, there's just one more thing we need: An offering.\n\nRelax, I don't mean a sacrifice. Just a bit of food.\n\nThere are sure to be mushrooms growing in Tideview Thicket to the northwest that are suitable for this. Please bring some.", progress = "Even the dead know hunger.", completion = "Thank you, {name}. These mushrooms may not seem like much of an offering, but the sentiment alone will be enough to draw the spirits to us.\n\nAlso, they make a pretty fine stir-fry.", objectives = "Gather 10 Tidemist Caps from Tideview Thicket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29757] = { id = 29757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bottletoads", description = "Have you heard about the crisis we're having at the pools?\n\nToads have moved in and are spawning like crazy! It's become a real problem for the lotus farmers.\n\nCoincidentally, I make a jam out of gelatinous toadspawn. I call it \"Bottletoads\" and it's a big hit with the kids around here. Can't keep any in stock.\n\nIf you're heading to the pools, you'd be doing everyone a favor by uh... liberating some of those toad eggs.\n\nInto this bottle. For me.\n\nJust look for bubbles and scoop right in!", progress = "\"It just ain't a party without Bottletoads!\"\n\nHmm... no, that doesn't work.\n\n\"Bottletoads: not as gross as they sound!\"", completion = "Now when the kids ask: \"Do you have Bottletoads?\" I can say YES!", objectives = "Scoop toad eggs from 8 Gurgling Toadspawn on the top level of the Pools of Purity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29758] = { id = 29758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guess Whose Back", description = "<This dragon turtle's massive shell is rock-hard and covered in sharp ridges. One of the locals could almost certainly make use of it.>", completion = "My MY now look at THIS! What a beautiful shell!\n\nYou were wise to bring this to me, my friend. It will make a fantastic serving platter.\n\nPlease, take this for your troubles.", objectives = "Bring Krosh's Back to Yan in New Cifera.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29759] = { id = 29759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kung Din", description = "I hope you are capable of this next task, for our lives depend on it.\n\nThere is only one key that will unlock our chains. Unfortunately, the key hangs around the neck of the hozen's pet tiger, Kung Din.\n\nThey keep the tiger in the great pit to the north. The only way to retrieve the key will be to kill the beast.", progress = "Did you find him?", completion = "Yes, with this key I will be able to free our chains.\n\nYou have delivered us from this vile place.", objectives = "Obtain the Slingtail Key by slaying Kung Din.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29760] = { id = 29760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pit Fighter", description = "There must be more to being a master pit fighter than this...\n\nPerhaps Korgol Crushskull who runs the Darkmoon Deathmatch at the Faire will know.", completion = "Well met, {class}.\n\nGaining but one trinket is not enough to make you a Master Pit Fighter.\n\nNow is the time to truly prove your steel.", objectives = "Speak with Korgol Crushskull at the Darkmoon Faire.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29761] = { id = 29761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master Pit Fighter", progress = "Well met again, {class}.\n\nBring me 12 trinkets of the Pit Fighter and then you shall be a Master Pit Fighter of the Darkmoon Deathmatch!", completion = "Many foes have you bested and many crowds entertained.\n\nI am glad to name you Master Pit Fighter of the Darkmoon Deathmatch!" }
quests[29762] = { id = 29762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Family Heirlooms", description = "We recently lost a fierce battle against the hozen at Moonwater Retreat.\n\nWe evacuated as many of our people as we could, but still, there were many we could not save.\n\nWe have no tokens of our lost over which to send our prayers.\n\nIf someone could go and retrieve heirlooms from the dead bodies, we could properly lay them to rest, and move on.\n\nIt would mean so much to us if you could do this, {name}.", progress = "We still grieve for our fallen brothers.", completion = "Thank you, {name}. You do not know how much this means to the families of the lost.", objectives = "Collect 8 Pearlfin Heirlooms from dead Pearlfin Villagers in Moonwater Retreat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29763] = { id = 29763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Their Thunder", description = "The vrykul are fearless in a fight. Seems they actually yearn fer a death in battle. With their numbers and that ferocity, we're doomed - plain and simple.\n\nThere's one they esteem though, goes by the name of Ingvar. Bring him down and you'll deal a mighty blow to their spirit.", progress = "Good to see you're well, {name}.\n\nWe've had about as many casualties as we can handle.", completion = "Outstanding!\n\nThis could be the turn of luck we've all been hoping for.", objectives = "Defender Mordun has asked you to acquire the head of Ingvar the Plunderer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29764] = { id = 29764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disarmament", description = "Take it from me, <lad/lass>, them vrykul weapons be downright nasty! Deceptively well-balanced, wickedly sharp - just plain deadly.\n\nI need you to pilfer some o' them weapons before they're used on us!", progress = "You pinch a load a' them vrykul axes?", completion = "<Mordun whistles.>\n\nWill ya just look at 'em? Incredible.\n\nI half expected these neanderthals to be swingin' around clubs and throwin' rock.\n\nNo such luck...", objectives = "Defender Mordun wants you to steal 5 Vrykul Weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29765] = { id = 29765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cryin' My Eyes Out", description = "I coulda taken out da whole lot of 'em, mon.\n\nShot 'em one by one, den played dead when dey be gettin' close. Fell for it every time, dey did - well almost every time...\n\nOne of 'em finally got wise. Called my bluff. Before I knew it, dey was usin' my eyes as marbles.\n\nRan off with my goods an' left me here ta die, da savages...\n\nHelp me, mon. Lemme die wit my dignity intact.", progress = "You got me goods, mon?", completion = "<Zin'Jun sobs...you think.>\n\nDey done killed Snuff...\n\nWhat'd 'ol Snuff ever do ta dem?", objectives = "Collect Zin'Jun's belongings from the Hozen Groundpounders.\n\nIf you lose Zin'Jun, speak to him at the Ascent of Swirling Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29766] = { id = 29766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Good Start", description = "Regardless of our predicament, our orders stand. We are to learn the lay of this land and prepare it for Hellscream's fleet.\n\nBut first, we must deal with these savages!\n\nYou see these corpses I've stacked up around the camp? I want mountains of them!\n\nWe are the Horde!\n\nThese vermin have not learned to fear us yet, but we will fix that soon enough...", objectives = "Kill 4 Hozen Mudflingers, 4 Hozen Skullthumpers, and 3 Hozen Fishcatchers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29767] = { id = 29767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fish Fry", description = "Fortune favors the bold!\n\nYour calculated aggressive actions have yielded unexpected rewards. If you can slay these fishcatchers after a successful haul, you'll inherit their slippery spoils.\n\nThinning out the enemy while feeding your allies - the picture of efficiency!", objectives = "Collect 12 Mature Carp from Hozu Fishcatchers", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29768] = { id = 29768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Mallet", description = "{name}, I've got it! It's simple really. Let's make a ruckus so loud that there's no way he can sleep through it.\n\nWhy look at that, a conveniently placed gong! Makes me think this may just be how they've awoken him in the past. We just need the matching mallet to get it ringing as loud as possible.\n\nThe village leader tells me the mallet is over at the Ki-Han Brewery on the river, to the southwest. It's not far. Mind picking it up for me while I give the village some fair warning?", progress = "Well, they're as warned as they're going to get. Do you have the mallet?", completion = "Hah, {name}! Now that's a mallet if I've ever seen one! Let's make some noise.", objectives = "Recover the Dai-Lo Recess Mallet at the Ki-Han Brewery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29769] = { id = 29769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rascals", description = "I'll keep trying to find ways to wake this stubborn little guy up, but there is no shortage of trouble on the island it seems. The crops to the south are infested with virmen, rabbit-like thieves and pillagers.\n\nRascals!\n\nThey breed faster than we can kill them! I have the perfect solution for such a situation: kill them faster! With you here, {name}, that shouldn't be a problem.", completion = "{name}, that's the way to do it! You show up, and problems start getting solved. That's just one of many reasons why I like you!", objectives = "Kill 10 Virmen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29770] = { id = 29770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still Good!", description = "The virmen to the south have been running off with all of our crops, but they're taking more than they can eat. They must be stockpiling them somewhere - the ones they like anyway.\n\nWill you go out and recover any of the uprooted crops you can find? I've got an island's worth of people to feed, and every single vegetable makes a difference.", progress = "Ever since Wugou. the spirit of earth, fell asleep, the dirt is drying out and it's getting harder and harder to get new seeds to sprout. We need to hold on to any food we can, or the island will have hard times ahead.", completion = "Some of these have mouth-sized chunks bitten out of them! Ah well, we can still make use.\n\nThank you for your help, friend.", objectives = "Recover 3 Uprooted Turnips, 3 Stolen Carrots, and 3 Pilfered Pumpkins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29771] = { id = 29771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stronger Than Wood", description = "Gather me wood planks from construction near the Ki-Han Brewery.\n\nYou do not yet know the extent of my strength, so I shall display it to you.", progress = "Have you done as I've asked?", completion = "Good.\n\nMy head, it is harder than the densest wood.\n\nStep back, and let me dispel your doubts.", objectives = "Gather 12 Discarded Wood Planks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29772] = { id = 29772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raucous Rousing", description = "You ready for this, {name}? I'm thinking maybe we should have looked for something to cover our ears, but it's a bit late for that now. Just remember that the intense ringing you'll be hearing for the next few hours is the ringing sound of victory!\n\nThe honor's all yours, {name}. Ring the gong whenever you're ready!", completion = "Huh... well... that's definitely the ringing I expected, but I was hoping for a bit more from Wugou. This guy's a deep sleeper, that's for sure.\n\nIt's alright, {name}. I've got another idea, and there's not much preparation needed at all - just how I like it.", objectives = "Ring the gong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29773] = { id = 29773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wugou, the Spirit of Earth", description = "{name}! Well, the plus side is that finding Wugou was easy enough. Waking him... not so much. I think he's going to wake quite sore from all the pushing and hitting I've done trying to rouse him.\n\nAre you a deep sleeper at all, {name}? What wakes you up in the morning?\n\nRolling out of bed always seems to do it for me, so I figure let's just go for that! I tied off some ropes to the ox cart. We send it running and give him a good roll, and we should be good! Care to give the ox a good slap to get it going?", objectives = "Slap the ox.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29774] = { id = 29774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not In the Face!", description = "Alright {name}, I was thinking about what we'd try next if the whole gong thing didn't work, and it came to me just like that! Water in the face always worked on me. It's got to be twice as effective for someone so dry and earthy!\n\nMind going over and asking Shu, the spirit of water, if he'll help us out?  He should be playing in the pool next to the waterfall, just on the other side of that tree.", completion = "YEAH!!! {name}, we make quite a team. Persistence over planning, I always say!", objectives = "Request Shu's help in waking Wugou, the spirit of earth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29775] = { id = 29775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spirit and Body of Shen-zin Su", description = "Well, that wraps it up here, doesn't it {name}?  Now that we've got these two roused and all friendly towards you, we just need to get them back to the Temple of Five Dawns.\n\nYou go ahead. I'm going to say my goodbyes, then I'll follow you up shortly.", completion = "You have done well, young student. Three of the four spirits have been returned to the temple. We are closer to the answers we seek.", objectives = "Bring Shu and Wugou, the spirits of water and earth, to the Temple of Five Dawns. A cart is waiting near the road to take you there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29776] = { id = 29776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morning Breeze Village", description = "The fourth and final spirit is Dafeng, the spirit of air. When he is not in the skies, he can be found on the Ridge of Laughing Winds to the west. I've sent both Aysa and Ji to help you find him.\n\nWhen you are ready, I will summon winds to carry you to the top of the temple. From there, cross the bridges to the west and find Ji in Morning Breeze Village.", completion = "{name}, give me a hug! Our parting was not so long this time - I quite prefer it that way!\n\nYou've been working with Aysa, have you not? Our disciplines have always kept us apart, so I know little of her. Watching her perform her exercises now, I must confess that she possesses a grace and discipline that is strangely alluring.\n\nThere are more pressing thoughts though, aren't there? {name}, let's take care of this monkey problem while we search for Dafeng.", objectives = "Meet with Ji Firepaw in Morning Breeze Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29777] = { id = 29777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools of the Enemy", description = "The hozen have stolen our brushes and are painting over our scrolls of wisdom with their own wisdoms, if you can call them that. If you're here to help, stop them and bring our brushes back before they can do more harm.", progress = "I do not wish to disparage the hozen for their aspirations - each race must walk its own path. In this moment, however, they are bringing harm to our bodies and our culture. That is a line that cannot be crossed.", completion = "I am very thankful, young one. I will soon begin the slow task of documenting all of our wisdoms again, so that the scrolls can be hung for the benefit of all to come.", objectives = "Retrieve 8 Paint Soaked Brushes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29778] = { id = 29778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rewritten Wisdoms", description = "{name}, we must help Elder Shaopai. There are few more deserving of our kindness.\n\nOn the way here, you surely noticed the scrolls of wisdom hanging in the grotto to the south. The hozen have defiled many of them, and sadly, they are not recoverable. We will deal with the problem directly - burn the defiled scrolls. Wipe the hozen writings away entirely.\n\nDo not worry for Elder Shaopai. The people shall come together and help him rewrite the wisdoms in time. I shall see to that.", completion = "You're a good man, {name}. You have proven that again and again, and I am glad to stand beside you.", objectives = "Burn 5 Defaced Scroll of Wisdom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29779] = { id = 29779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Direct Solution", description = "Alright {name}, this is the second time we've had to deal with ravaging hozen. I think it's time we take care of this problem the Huojin way. No more patience. No more mediation. We go to the source.\n\nWe're going into the hozen village to the north and we're punishing those smelly troublemakers. I've been looking forward to a chance to fight by your side again, {name}.", completion = "Invigorating! A good fight always makes me feel better!", objectives = "Kill 20 hozen in Fe-Feng Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29780] = { id = 29780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do No Evil", description = "{name}, I need you to understand that the way of the Huojin is not the way of violence. When fighting is needed, we will not hesitate, but when fighting is not needed, neither do we instigate. However, the direct solution is often cutting the head off the snake, as they say.\n\nThe hozen have a leader instigating these attacks. If we remove Ruk-Ruk, we won't have to wipe the hozen out entirely.\n\nI know you are not of the Huojin, but are you with me in what must be done, {name}?", completion = "{name}, I think you've got a bit of Huojin in you. Stick with me and I'll bring you around, I think.", objectives = "Kill Ruk-ruk, the Fe-Feng Chief.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29781] = { id = 29781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monkey Advisory Warning", description = "The monkeys have been stealing from the village during their attacks. We should be fine without some of the extra food stores, but the idea of monkeys with fireworks... I'm a little bit concerned. Not to mention, who knows when some fireworks will come in handy?\n\nHelp me recover the stolen fireworks from their village, {name}?", progress = "I'm somewhat impressed they hadn't set their village on fire with these things.", completion = "{name}, I'm thinking we should celebrate with these later. What do you think?", objectives = "Recover 8 Stolen Firework Bundles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29782] = { id = 29782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stronger Than Bone", description = "This giant jade tiger pillar doesn't seem to fit in amidst the hozen buildings.\n\nWhat it does seem is very hard. Very solid.\n\nYou know just the person to bring this to.", completion = "GOOD! A true challenge. Let us put this pillar to the test!", objectives = "Bring the Jade Tiger Pillar to Jojo Ironbrow in Morning Breeze Village.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29783] = { id = 29783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stronger Than Stone", description = "Gather me stone blocks from the Ridge of Laughing Winds to the south.\n\nYou have seen my strength twice, yet I still spy doubt within your eyes. It will not last.", progress = "The strength of the body cannot exist without the strength of the mind.", completion = "Good.\n\nMy head, it is harder than the strongest stone.\n\nStep back, and let me dispel your doubts.", objectives = "Gather 12 Abandoned Stone Blocks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29784] = { id = 29784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balanced Perspective", description = "Aysa has been meditating on the lake since we've arrived, all her thoughts focused on Dafeng. I don't know what she hopes to discover out there, but she's no fool, and Master Shang Xi has entrusted this task with her.\n\nYou will need to cross the ropes leading from the end of the dock to reach her. It shall test your balance, but I think you're up to the task, {name}.", completion = "I'm impressed. Most students that are even capable of reaching this spot do so soaking wet.", objectives = "Cross the ropes and speak to Aysa Cloudsinger on Morning Breeze Lake.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29785] = { id = 29785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dafeng, the Spirit of Air", description = "If you listen long enough, the wind will carry the answer to you.\n\nDafeng, the spirit of air, has been scared from the skies by Zhao-Ren, the Onyx Serpent. He hides within the Chamber of Whispers, at the south side of the plateau.\n\nGo to him. Ji and I will join you there.", completion = "Dafeng looks frightened as you approach, but settles a bit at the sound of your voice.", objectives = "Speak to Dafeng, the spirit of air, in the Chamber of Whispers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29786] = { id = 29786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for the Skies", description = "Dafeng, the spirit of air, is terrified by Zhao-Ren, the Onyx Serpent. We must help him face that fear, or face it for him ourselves.\n\nWhen I told Ji of the serpent, he said he had an idea and would begin preparations outside of the chamber. Despite his rash nature, I must admit, I envy his passion and conviction.\n\nLet us go outside and confront the Onyx Serpent.", completion = "You have helped Dafeng, the spirit of air, find his courage! The final spirit has been restored.", objectives = "Defeat Zhao-Ren, the Onyx Serpent with the aid of Ji's fireworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29787] = { id = 29787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worthy of Passing", description = "The four elemental spirits will help you speak with the land and uncover its plight, but first, I have one small task to ask of you.\n\nJoin me, my pupil. Accompany this old pandaren to the western grove.", completion = "I do not have the strength of body or will that I once did. I'm glad there are noble {race} like you to fight on for our people. You've come far, {name}.", objectives = "Defeat the Guardian of the Elders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29788] = { id = 29788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwelcome Nature", description = "You faced forest sprites in the Dawning Valley, but the forest sprites in this grove are a different breed. Crueler and more dangerous.\n\nIf you would clear some of these sprites out, the spirits would thank you.", completion = "The spirits thank you, {class}.", objectives = "Kill 8 Thornbranch Scamps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29789] = { id = 29789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Small, But Significant", description = "I am tired, {name}. I must rest.\n\nWe have a ritual to perform, but we require some of the charms from this grove. If you wander the grove, you should see them all over hanging from the trees. \n\nIf it does not offend one as young as you, will you permit me to sit and recover my strength while you gather these charms?", progress = "Rest feels good. The burdens of life have become a great weight after so many years.", completion = "You come through, as you always have. You are truly one of my greatest students. I think you will be something the likes of which the world has never seen.", objectives = "Retrieve 8 Kun-Pai Ritual Charms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29790] = { id = 29790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Passing Wisdom", description = "This journey shall soon be yours to undertake without me. Stay for a few moments and listen to an old man's words. Let my knowledge serve as a foundation for yours, that you might be greater than I ever was.", completion = "I know, {name}... I know. Such is the way of things.", objectives = "Listen to Master Shang Xi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29791] = { id = 29791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Suffering of Shen-zin Su", description = "Now is not the time to grieve. The balloon is ready, and Shen-zin Su awaits.\n\nWe shall be the first pandaren to speak to Shen-zin Su in hundreds of years. It is a great honor.", completion = "You have undergone a great honor, {class}. Have you come back wiser for it?", objectives = "Board the Hot Air Balloon and Speak to Shen-zin Su.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29792] = { id = 29792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bidden to Greatness", description = "It is up to all of you to remove the thorn from the side of Shen-zin Su. Do not let your differences come between you. Trust in each other.\n\nWithin the Pei-Wu Forest is a lone hermit. Head directly to his hut. He knows intimately of the dark things that now lurk in the trees.", completion = "Evil is rising from the seas and filling the forest. It's not just tigers anymore... something far more sinister lurks in the shadows, waiting to take any {race} unwise enough to stray out alone.\n\nYou are not safe here.", objectives = "Open the gates to Pei-Wu Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29793] = { id = 29793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evil from the Seas", description = "I do not know what this evil is that is infesting the forest, {name}, but I know exactly how to deal with it. So do you, I think.", completion = "You make me proud, {name}. You make all of us proud.", objectives = "Kill 8 Darkened Horrors or Darkened Terrors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29794] = { id = 29794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "None Left Behind", description = "Your friend has been doing everything she can to save my crew. I'm deeply appreciative.\n\nWe're still dealing with more than we can handle here: quenching the fires on the wreckage, getting my people out, fighting off these evil sea creatures, and trying to prevent the prisoners from escaping. We're simply in over our heads.\n\nI still have men on the ship that we need to get clear before the wreckage collapses on them. I know this is asking a lot, but can you help?", completion = "I have no idea who you people are, but fate surely smiled on us this day. Many more would be dead if not for the help of you and your friends. I am in your debt.", objectives = "Rescue 3 Injured Sailors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
